void TwistExpander_Castor::Seed(TwistWorkSpace *pWorkSpace,
                                 TwistFarmSalt *pFarmSalt,
                                 std::uint64_t pNonce,
                                 std::uint8_t *pPassword,
                                 std::size_t pPasswordByteLength,
                                 std::uint8_t *pDestination) {
    if ((pWorkSpace == nullptr) || (pFarmSalt == nullptr) ||
        (pDestination == nullptr)) { return; }

    UnrollPassword(pWorkSpace->mSourceLane, pPassword, pPasswordByteLength);
    UnrollNonce(pWorkSpace->mNonceLane, pNonce);
    mDomainBundleInbuilt.mKeyRotateASalts = kKeyRotateASalts;
    mDomainBundleInbuilt.mKeyRotateAConstants = kKeyRotateAConstants;
    mDomainBundleInbuilt.mKeyRotateBSalts = kKeyRotateBSalts;
    mDomainBundleInbuilt.mKeyRotateBConstants = kKeyRotateBConstants;
    mDomainBundleInbuilt.mKeySpawnASalts = kKeySpawnASalts;
    mDomainBundleInbuilt.mKeySpawnAConstants = kKeySpawnAConstants;
    mDomainBundleInbuilt.mKeySpawnBSalts = kKeySpawnBSalts;
    mDomainBundleInbuilt.mKeySpawnBConstants = kKeySpawnBConstants;
    mDomainBundleInbuilt.mSeedSalts = kSeedSalts;
    mDomainBundleInbuilt.mSeedConstants = kSeedConstants;
    mDomainBundleInbuilt.mTwistSalts = kTwistSalts;
    mDomainBundleInbuilt.mTwistConstants = kTwistConstants;
    mDomainBundleEphemeralA.Zero();
    mDomainBundleEphemeralB.Zero();
    pWorkSpace->mDomainBundle.Zero();
    std::uint8_t *aSpiritLaneA = pWorkSpace->mSpiritLaneA;
    std::uint8_t *aSpiritLaneB = pWorkSpace->mSpiritLaneB;
    std::uint8_t *aSpiritLaneC = pWorkSpace->mSpiritLaneC;
    std::uint8_t *aSpiritLaneD = pWorkSpace->mSpiritLaneD;
    std::uint8_t *aFireLaneA = pWorkSpace->mFireLaneA;
    std::uint8_t *aFireLaneB = pWorkSpace->mFireLaneB;
    std::uint8_t *aFireLaneC = pWorkSpace->mFireLaneC;
    std::uint8_t *aFireLaneD = pWorkSpace->mFireLaneD;
    std::uint8_t *aWaterLaneA = pWorkSpace->mWaterLaneA;
    std::uint8_t *aWaterLaneB = pWorkSpace->mWaterLaneB;
    std::uint8_t *aWaterLaneC = pWorkSpace->mWaterLaneC;
    std::uint8_t *aWaterLaneD = pWorkSpace->mWaterLaneD;
    std::uint8_t *aHeartLaneA = pWorkSpace->mHeartLaneA;
    std::uint8_t *aHeartLaneB = pWorkSpace->mHeartLaneB;
    std::uint8_t *aHeartLaneC = pWorkSpace->mHeartLaneC;
    std::uint8_t *aHeartLaneD = pWorkSpace->mHeartLaneD;
    std::uint8_t *aWindLaneA = pWorkSpace->mWindLaneA;
    std::uint8_t *aWindLaneB = pWorkSpace->mWindLaneB;
    std::uint8_t *aWindLaneC = pWorkSpace->mWindLaneC;
    std::uint8_t *aWindLaneD = pWorkSpace->mWindLaneD;
    std::uint8_t *aFuseLaneA = pWorkSpace->mFuseLaneA;
    std::uint8_t *aFuseLaneB = pWorkSpace->mFuseLaneB;
    std::uint8_t *aFuseLaneC = pWorkSpace->mFuseLaneC;
    std::uint8_t *aLightningLaneA = pWorkSpace->mLightningLaneA;
    std::uint8_t *aLightningLaneB = pWorkSpace->mLightningLaneB;
    std::uint8_t *aLightningLaneC = pWorkSpace->mLightningLaneC;
    std::uint8_t *aLightningLaneD = pWorkSpace->mLightningLaneD;
    std::uint8_t *aPlasmaLaneA = pWorkSpace->mPlasmaLaneA;
    std::uint8_t *aPlasmaLaneB = pWorkSpace->mPlasmaLaneB;
    std::uint8_t *aPlasmaLaneC = pWorkSpace->mPlasmaLaneC;
    std::uint8_t *aPlasmaLaneD = pWorkSpace->mPlasmaLaneD;
    std::uint8_t *aShadowLaneA = pWorkSpace->mShadowLaneA;
    std::uint8_t *aShadowLaneB = pWorkSpace->mShadowLaneB;
    std::uint8_t *aShadowLaneC = pWorkSpace->mShadowLaneC;
    std::uint8_t *aShadowLaneD = pWorkSpace->mShadowLaneD;
    std::uint8_t *aAetherLaneA = pWorkSpace->mAetherLaneA;
    std::uint8_t *aAetherLaneB = pWorkSpace->mAetherLaneB;
    std::uint8_t *aAetherLaneC = pWorkSpace->mAetherLaneC;
    std::uint8_t *aAetherLaneD = pWorkSpace->mAetherLaneD;
    std::uint8_t *aCelestialLaneA = pWorkSpace->mCelestialLaneA;
    std::uint8_t *aCelestialLaneB = pWorkSpace->mCelestialLaneB;
    std::uint8_t *aCelestialLaneC = pWorkSpace->mCelestialLaneC;
    std::uint8_t *aCelestialLaneD = pWorkSpace->mCelestialLaneD;
    std::uint8_t *aVaporLaneA = pWorkSpace->mVaporLaneA;
    std::uint8_t *aVaporLaneB = pWorkSpace->mVaporLaneB;
    std::uint8_t *aVaporLaneC = pWorkSpace->mVaporLaneC;
    std::uint8_t *aVaporLaneD = pWorkSpace->mVaporLaneD;
    std::uint8_t *aKineticLaneA = pWorkSpace->mKineticLaneA;
    std::uint8_t *aKineticLaneB = pWorkSpace->mKineticLaneB;
    std::uint8_t *aKineticLaneC = pWorkSpace->mKineticLaneC;
    std::uint8_t *aKineticLaneD = pWorkSpace->mKineticLaneD;
    std::uint8_t *aSonicLaneA = pWorkSpace->mSonicLaneA;
    std::uint8_t *aSonicLaneB = pWorkSpace->mSonicLaneB;
    std::uint8_t *aSonicLaneC = pWorkSpace->mSonicLaneC;
    std::uint8_t *aSonicLaneD = pWorkSpace->mSonicLaneD;
    std::uint8_t *aPlanarLaneA = pWorkSpace->mPlanarLaneA;
    std::uint8_t *aPlanarLaneB = pWorkSpace->mPlanarLaneB;
    std::uint8_t *aPlanarLaneC = pWorkSpace->mPlanarLaneC;
    std::uint8_t *aPlanarLaneD = pWorkSpace->mPlanarLaneD;
    std::uint8_t *aFrostLaneA = pWorkSpace->mFrostLaneA;
    std::uint8_t *aFrostLaneB = pWorkSpace->mFrostLaneB;
    std::uint8_t *aFrostLaneC = pWorkSpace->mFrostLaneC;
    std::uint8_t *aFrostLaneD = pWorkSpace->mFrostLaneD;
    std::uint8_t *aArcaneLaneA = pWorkSpace->mArcaneLaneA;
    std::uint8_t *aArcaneLaneB = pWorkSpace->mArcaneLaneB;
    std::uint8_t *aArcaneLaneC = pWorkSpace->mArcaneLaneC;
    std::uint8_t *aArcaneLaneD = pWorkSpace->mArcaneLaneD;
    std::uint8_t *aLunarLaneA = pWorkSpace->mLunarLaneA;
    std::uint8_t *aLunarLaneB = pWorkSpace->mLunarLaneB;
    std::uint8_t *aLunarLaneC = pWorkSpace->mLunarLaneC;
    std::uint8_t *aLunarLaneD = pWorkSpace->mLunarLaneD;
    std::uint8_t *aRunicLaneA = pWorkSpace->mRunicLaneA;
    std::uint8_t *aRunicLaneB = pWorkSpace->mRunicLaneB;
    std::uint8_t *aRunicLaneC = pWorkSpace->mRunicLaneC;
    std::uint8_t *aRunicLaneD = pWorkSpace->mRunicLaneD;
    std::uint8_t *aGloomLaneA = pWorkSpace->mGloomLaneA;
    std::uint8_t *aGloomLaneB = pWorkSpace->mGloomLaneB;
    std::uint8_t *aGloomLaneC = pWorkSpace->mGloomLaneC;
    std::uint8_t *aGloomLaneD = pWorkSpace->mGloomLaneD;
    std::uint8_t *aAbjurationLaneA = pWorkSpace->mAbjurationLaneA;
    std::uint8_t *aAbjurationLaneB = pWorkSpace->mAbjurationLaneB;
    std::uint8_t *aAbjurationLaneC = pWorkSpace->mAbjurationLaneC;
    std::uint8_t *aAbjurationLaneD = pWorkSpace->mAbjurationLaneD;
    std::uint8_t *aDivinationLaneA = pWorkSpace->mDivinationLaneA;
    std::uint8_t *aDivinationLaneB = pWorkSpace->mDivinationLaneB;
    std::uint8_t *aDivinationLaneC = pWorkSpace->mDivinationLaneC;
    std::uint8_t *aDivinationLaneD = pWorkSpace->mDivinationLaneD;
    std::uint8_t *aEvocationLaneA = pWorkSpace->mEvocationLaneA;
    std::uint8_t *aEvocationLaneB = pWorkSpace->mEvocationLaneB;
    std::uint8_t *aEvocationLaneC = pWorkSpace->mEvocationLaneC;
    std::uint8_t *aEvocationLaneD = pWorkSpace->mEvocationLaneD;
    std::uint8_t *aStasisLaneA = pWorkSpace->mStasisLaneA;
    std::uint8_t *aStasisLaneB = pWorkSpace->mStasisLaneB;
    std::uint8_t *aStasisLaneC = pWorkSpace->mStasisLaneC;
    std::uint8_t *aStasisLaneD = pWorkSpace->mStasisLaneD;
    std::uint8_t *aMysticalLaneA = pWorkSpace->mMysticalLaneA;
    std::uint8_t *aMysticalLaneB = pWorkSpace->mMysticalLaneB;
    std::uint8_t *aMysticalLaneC = pWorkSpace->mMysticalLaneC;
    std::uint8_t *aMysticalLaneD = pWorkSpace->mMysticalLaneD;
    std::uint8_t *aCovenLaneA = pWorkSpace->mCovenLaneA;
    std::uint8_t *aCovenLaneB = pWorkSpace->mCovenLaneB;
    std::uint8_t *aCovenLaneC = pWorkSpace->mCovenLaneC;
    std::uint8_t *aCovenLaneD = pWorkSpace->mCovenLaneD;
    std::uint8_t *aIceLaneA = pWorkSpace->mIceLaneA;
    std::uint8_t *aIceLaneB = pWorkSpace->mIceLaneB;
    std::uint8_t *aIceLaneC = pWorkSpace->mIceLaneC;
    std::uint8_t *aIceLaneD = pWorkSpace->mIceLaneD;
    std::size_t *aIndexList256A = pWorkSpace->mIndexList256A;
    std::size_t *aIndexList256B = pWorkSpace->mIndexList256B;
    std::size_t *aIndexList256C = pWorkSpace->mIndexList256C;
    std::size_t *aIndexList256D = pWorkSpace->mIndexList256D;

    std::uint64_t aIngress = 0xA1B6BAC69FCACFDDULL;
    std::uint64_t aCarry = 0x9E0B0638C79D3DA8ULL;
    std::uint64_t aWandererA = 0x9BAC73B186653A59ULL;
    std::uint64_t aWandererB = 0x9C2EAA3CFA647575ULL;
    std::uint64_t aWandererC = 0xCFBA81FE588FE499ULL;
    std::uint64_t aWandererD = 0xE27F8981402FE613ULL;
    std::uint64_t aWandererE = 0xB84B490027989E16ULL;
    std::uint64_t aWandererF = 0xB66A72BB1C58A808ULL;
    std::uint64_t aWandererG = 0xBB485701E4FD6C73ULL;
    std::uint64_t aWandererH = 0xE3BC0258CB8D8D07ULL;
    std::uint64_t aWandererI = 0xFF87BFC2DCA6D2BEULL;
    std::uint64_t aWandererJ = 0x87453C0C2579BF54ULL;
    std::uint64_t aWandererK = 0xD99AEB7C20EDB611ULL;

    ////////////////////////////////////////////////////////
    //
    // Secret material derivation, across 6 domains.
    //
    // Domain 1 of 6, key a rotate:
    //
    KDF_A_A(pWorkSpace, pNonce, &(mDomainBundleInbuilt.mKeyRotateAConstants), &(mDomainBundleInbuilt.mKeyRotateASalts), ARX_STATE_VARS);

    TwistFarm::Farm(pFarmSalt,
                    aIceLaneB, aIceLaneC, aIceLaneD, aIceLaneA, // farm lanes
                    aFuseLaneA, aFuseLaneB, aFuseLaneC, // temp/fold lanes
                    &mDomainBundleEphemeralA.mKeyRotateASalts,
                    &(mDomainBundleEphemeralA.mKeyRotateAConstants));

    KDF_B_A(pWorkSpace, pNonce, &(mDomainBundleEphemeralA.mKeyRotateAConstants), &(mDomainBundleEphemeralA.mKeyRotateASalts), ARX_STATE_VARS);

    TwistFarm::Farm(pFarmSalt,
                    aVaporLaneB, aVaporLaneC, aVaporLaneD, aVaporLaneA, // farm lanes
                    aFuseLaneA, aFuseLaneB, aFuseLaneC, // temp/fold lanes
                    &mDomainBundleEphemeralB.mKeyRotateASalts,
                    &(mDomainBundleEphemeralB.mKeyRotateAConstants));

    KDF_C_A(pWorkSpace, pNonce, &(mDomainBundleEphemeralB.mKeyRotateAConstants), &(mDomainBundleEphemeralB.mKeyRotateASalts), ARX_STATE_VARS);

    TwistFarm::Farm(pFarmSalt,
                    aCelestialLaneB, aCelestialLaneC, aCelestialLaneD, aCelestialLaneA, // farm lanes
                    aFuseLaneA, aFuseLaneB, aFuseLaneC, // temp/fold lanes
                    &pWorkSpace->mDomainBundle.mKeyRotateASalts,
                    &(pWorkSpace->mDomainBundle.mKeyRotateAConstants));
    //
    // Domain 2 of 6, key b rotate:
    //
    KDF_A_B(pWorkSpace, pNonce, &(mDomainBundleInbuilt.mKeyRotateBConstants), &(mDomainBundleInbuilt.mKeyRotateBSalts), ARX_STATE_VARS);

    TwistFarm::Farm(pFarmSalt,
                    aIceLaneB, aIceLaneC, aIceLaneD, aIceLaneA, // farm lanes
                    aFuseLaneA, aFuseLaneB, aFuseLaneC, // temp/fold lanes
                    &mDomainBundleEphemeralA.mKeyRotateBSalts,
                    &(mDomainBundleEphemeralA.mKeyRotateBConstants));

    KDF_B_B(pWorkSpace, pNonce, &(mDomainBundleEphemeralA.mKeyRotateBConstants), &(mDomainBundleEphemeralA.mKeyRotateBSalts), ARX_STATE_VARS);

    TwistFarm::Farm(pFarmSalt,
                    aVaporLaneB, aVaporLaneC, aVaporLaneD, aVaporLaneA, // farm lanes
                    aFuseLaneA, aFuseLaneB, aFuseLaneC, // temp/fold lanes
                    &mDomainBundleEphemeralB.mKeyRotateBSalts,
                    &(mDomainBundleEphemeralB.mKeyRotateBConstants));

    KDF_C_B(pWorkSpace, pNonce, &(mDomainBundleEphemeralB.mKeyRotateBConstants), &(mDomainBundleEphemeralB.mKeyRotateBSalts), ARX_STATE_VARS);

    TwistFarm::Farm(pFarmSalt,
                    aCelestialLaneB, aCelestialLaneC, aCelestialLaneD, aCelestialLaneA, // farm lanes
                    aFuseLaneA, aFuseLaneB, aFuseLaneC, // temp/fold lanes
                    &pWorkSpace->mDomainBundle.mKeyRotateBSalts,
                    &(pWorkSpace->mDomainBundle.mKeyRotateBConstants));
    //
    // Domain 3 of 6, key a spawn:
    //
    KDF_A_C(pWorkSpace, pNonce, &(mDomainBundleInbuilt.mKeySpawnAConstants), &(mDomainBundleInbuilt.mKeySpawnASalts), ARX_STATE_VARS);

    TwistFarm::Farm(pFarmSalt,
                    aIceLaneB, aIceLaneC, aIceLaneD, aIceLaneA, // farm lanes
                    aFuseLaneA, aFuseLaneB, aFuseLaneC, // temp/fold lanes
                    &mDomainBundleEphemeralA.mKeySpawnASalts,
                    &(mDomainBundleEphemeralA.mKeySpawnAConstants));

    KDF_B_C(pWorkSpace, pNonce, &(mDomainBundleEphemeralA.mKeySpawnAConstants), &(mDomainBundleEphemeralA.mKeySpawnASalts), ARX_STATE_VARS);

    TwistFarm::Farm(pFarmSalt,
                    aVaporLaneB, aVaporLaneC, aVaporLaneD, aVaporLaneA, // farm lanes
                    aFuseLaneA, aFuseLaneB, aFuseLaneC, // temp/fold lanes
                    &mDomainBundleEphemeralB.mKeySpawnASalts,
                    &(mDomainBundleEphemeralB.mKeySpawnAConstants));

    KDF_C_C(pWorkSpace, pNonce, &(mDomainBundleEphemeralB.mKeySpawnAConstants), &(mDomainBundleEphemeralB.mKeySpawnASalts), ARX_STATE_VARS);

    TwistFarm::Farm(pFarmSalt,
                    aCelestialLaneB, aCelestialLaneC, aCelestialLaneD, aCelestialLaneA, // farm lanes
                    aFuseLaneA, aFuseLaneB, aFuseLaneC, // temp/fold lanes
                    &pWorkSpace->mDomainBundle.mKeySpawnASalts,
                    &(pWorkSpace->mDomainBundle.mKeySpawnAConstants));
    //
    // Domain 4 of 6, key b spawn:
    //
    KDF_A_D(pWorkSpace, pNonce, &(mDomainBundleInbuilt.mKeySpawnBConstants), &(mDomainBundleInbuilt.mKeySpawnBSalts), ARX_STATE_VARS);

    TwistFarm::Farm(pFarmSalt,
                    aIceLaneB, aIceLaneC, aIceLaneD, aIceLaneA, // farm lanes
                    aFuseLaneA, aFuseLaneB, aFuseLaneC, // temp/fold lanes
                    &mDomainBundleEphemeralA.mKeySpawnBSalts,
                    &(mDomainBundleEphemeralA.mKeySpawnBConstants));

    KDF_B_D(pWorkSpace, pNonce, &(mDomainBundleEphemeralA.mKeySpawnBConstants), &(mDomainBundleEphemeralA.mKeySpawnBSalts), ARX_STATE_VARS);

    TwistFarm::Farm(pFarmSalt,
                    aVaporLaneB, aVaporLaneC, aVaporLaneD, aVaporLaneA, // farm lanes
                    aFuseLaneA, aFuseLaneB, aFuseLaneC, // temp/fold lanes
                    &mDomainBundleEphemeralB.mKeySpawnBSalts,
                    &(mDomainBundleEphemeralB.mKeySpawnBConstants));

    KDF_C_D(pWorkSpace, pNonce, &(mDomainBundleEphemeralB.mKeySpawnBConstants), &(mDomainBundleEphemeralB.mKeySpawnBSalts), ARX_STATE_VARS);

    TwistFarm::Farm(pFarmSalt,
                    aCelestialLaneB, aCelestialLaneC, aCelestialLaneD, aCelestialLaneA, // farm lanes
                    aFuseLaneA, aFuseLaneB, aFuseLaneC, // temp/fold lanes
                    &pWorkSpace->mDomainBundle.mKeySpawnBSalts,
                    &(pWorkSpace->mDomainBundle.mKeySpawnBConstants));
    //
    // Domain 5 of 6, twist:
    //
    KDF_A_E(pWorkSpace, pNonce, &(mDomainBundleInbuilt.mTwistConstants), &(mDomainBundleInbuilt.mTwistSalts), ARX_STATE_VARS);

    TwistFarm::Farm(pFarmSalt,
                    aIceLaneB, aIceLaneC, aIceLaneD, aIceLaneA, // farm lanes
                    aFuseLaneA, aFuseLaneB, aFuseLaneC, // temp/fold lanes
                    &mDomainBundleEphemeralA.mTwistSalts,
                    &(mDomainBundleEphemeralA.mTwistConstants));

    KDF_B_E(pWorkSpace, pNonce, &(mDomainBundleEphemeralA.mTwistConstants), &(mDomainBundleEphemeralA.mTwistSalts), ARX_STATE_VARS);

    TwistFarm::Farm(pFarmSalt,
                    aVaporLaneB, aVaporLaneC, aVaporLaneD, aVaporLaneA, // farm lanes
                    aFuseLaneA, aFuseLaneB, aFuseLaneC, // temp/fold lanes
                    &mDomainBundleEphemeralB.mTwistSalts,
                    &(mDomainBundleEphemeralB.mTwistConstants));

    KDF_C_E(pWorkSpace, pNonce, &(mDomainBundleEphemeralB.mTwistConstants), &(mDomainBundleEphemeralB.mTwistSalts), ARX_STATE_VARS);

    TwistFarm::Farm(pFarmSalt,
                    aCelestialLaneB, aCelestialLaneC, aCelestialLaneD, aCelestialLaneA, // farm lanes
                    aFuseLaneA, aFuseLaneB, aFuseLaneC, // temp/fold lanes
                    &pWorkSpace->mDomainBundle.mTwistSalts,
                    &(pWorkSpace->mDomainBundle.mTwistConstants));
    //
    // Domain 6 of 6, seed:
    //
    KDF_A_F(pWorkSpace, pNonce, &(mDomainBundleInbuilt.mSeedConstants), &(mDomainBundleInbuilt.mSeedSalts), ARX_STATE_VARS);

    TwistFarm::Farm(pFarmSalt,
                    aIceLaneB, aIceLaneC, aIceLaneD, aIceLaneA, // farm lanes
                    aFuseLaneA, aFuseLaneB, aFuseLaneC, // temp/fold lanes
                    &mDomainBundleEphemeralA.mSeedSalts,
                    &(mDomainBundleEphemeralA.mSeedConstants));

    KDF_B_F(pWorkSpace, pNonce, &(mDomainBundleEphemeralA.mSeedConstants), &(mDomainBundleEphemeralA.mSeedSalts), ARX_STATE_VARS);

    TwistFarm::Farm(pFarmSalt,
                    aVaporLaneB, aVaporLaneC, aVaporLaneD, aVaporLaneA, // farm lanes
                    aFuseLaneA, aFuseLaneB, aFuseLaneC, // temp/fold lanes
                    &mDomainBundleEphemeralB.mSeedSalts,
                    &(mDomainBundleEphemeralB.mSeedConstants));

    KDF_C_F(pWorkSpace, pNonce, &(mDomainBundleEphemeralB.mSeedConstants), &(mDomainBundleEphemeralB.mSeedSalts), ARX_STATE_VARS);

    TwistFarm::Farm(pFarmSalt,
                    aCelestialLaneB, aCelestialLaneC, aCelestialLaneD, aCelestialLaneA, // farm lanes
                    aFuseLaneA, aFuseLaneB, aFuseLaneC, // temp/fold lanes
                    &pWorkSpace->mDomainBundle.mSeedSalts,
                    &(pWorkSpace->mDomainBundle.mSeedConstants));
    //
    ////////////////////////////////////////////////////////


    ////////////////////////////////////////////////////////
    //
    // Main seed loops
    //
    TwistExpander_Castor_Arx::SEED_A(PARAMS_SEED);

    TwistExpander_Castor_Arx::SEED_B(PARAMS_SEED);

    std::uint64_t aDomainWordMatrixSelectA = pWorkSpace->mDomainBundle.mSeedConstants.mMatrixSelectA;
    std::uint64_t aDomainWordMatrixSelectB = pWorkSpace->mDomainBundle.mSeedConstants.mMatrixSelectB;

    std::uint8_t aDomainWordMatrixUnrollA = pWorkSpace->mDomainBundle.mSeedConstants.mMatrixUnrollA;
    std::uint8_t aDomainWordMatrixUnrollB = pWorkSpace->mDomainBundle.mSeedConstants.mMatrixUnrollB;

    std::uint8_t aDomainWordMatrixArgA = pWorkSpace->mDomainBundle.mSeedConstants.mMatrixArgA;
    std::uint8_t aDomainWordMatrixArgB = pWorkSpace->mDomainBundle.mSeedConstants.mMatrixArgB;
    std::uint8_t aDomainWordMatrixArgC = pWorkSpace->mDomainBundle.mSeedConstants.mMatrixArgC;
    std::uint8_t aDomainWordMatrixArgD = pWorkSpace->mDomainBundle.mSeedConstants.mMatrixArgD;

    TwistDiffuse::DiffuseWithDomainWords(
        aSpiritLaneA, aSpiritLaneB, aSpiritLaneC, aSpiritLaneD,  // input lanes
        aStasisLaneA, aStasisLaneB, aStasisLaneC, aStasisLaneD, // output lanes
        aWaterLaneA, aWaterLaneB, aWaterLaneC, aWaterLaneD, // entropy lanes
        aIndexList256A, aIndexList256B, aIndexList256C, aIndexList256D, &mMatrix, aDomainWordMatrixSelectA, aDomainWordMatrixSelectB, aDomainWordMatrixUnrollA, aDomainWordMatrixUnrollB, aDomainWordMatrixArgA, aDomainWordMatrixArgB, aDomainWordMatrixArgC, aDomainWordMatrixArgD);

    TwistExpander_Castor_Arx::SEED_C(PARAMS_SEED);

    TwistExpander_Castor_Arx::SEED_D(PARAMS_SEED);

    TwistDiffuse::DiffuseWithDomainWords(
        aWindLaneA, aWindLaneB, aWindLaneC, aWindLaneD,  // input lanes
        aVaporLaneA, aVaporLaneB, aVaporLaneC, aVaporLaneD, // output lanes
        aLightningLaneA, aLightningLaneB, aLightningLaneC, aLightningLaneD, // entropy lanes
        aIndexList256A, aIndexList256B, aIndexList256C, aIndexList256D, &mMatrix, aDomainWordMatrixSelectA, aDomainWordMatrixSelectB, aDomainWordMatrixUnrollA, aDomainWordMatrixUnrollB, aDomainWordMatrixArgA, aDomainWordMatrixArgB, aDomainWordMatrixArgC, aDomainWordMatrixArgD);

    TwistExpander_Castor_Arx::SEED_E(PARAMS_SEED);

    TwistExpander_Castor_Arx::SEED_F(PARAMS_SEED);

    TwistDiffuse::DiffuseWithDomainWords(
        aAetherLaneA, aAetherLaneB, aAetherLaneC, aAetherLaneD,  // input lanes
        aShadowLaneA, aShadowLaneB, aShadowLaneC, aShadowLaneD, // output lanes
        aPlasmaLaneA, aPlasmaLaneB, aPlasmaLaneC, aPlasmaLaneD, // entropy lanes
        aIndexList256A, aIndexList256B, aIndexList256C, aIndexList256D, &mMatrix, aDomainWordMatrixSelectA, aDomainWordMatrixSelectB, aDomainWordMatrixUnrollA, aDomainWordMatrixUnrollB, aDomainWordMatrixArgA, aDomainWordMatrixArgB, aDomainWordMatrixArgC, aDomainWordMatrixArgD);

    TwistExpander_Castor_Arx::SEED_G(PARAMS_SEED);

    TwistExpander_Castor_Arx::SEED_H(PARAMS_SEED);

    TwistDiffuse::DiffuseWithDomainWords(
        aKineticLaneA, aKineticLaneB, aKineticLaneC, aKineticLaneD,  // input lanes
        aSonicLaneA, aSonicLaneB, aSonicLaneC, aSonicLaneD, // output lanes
        aMysticalLaneA, aMysticalLaneB, aMysticalLaneC, aMysticalLaneD, // entropy lanes
        aIndexList256A, aIndexList256B, aIndexList256C, aIndexList256D, &mMatrix, aDomainWordMatrixSelectA, aDomainWordMatrixSelectB, aDomainWordMatrixUnrollA, aDomainWordMatrixUnrollB, aDomainWordMatrixArgA, aDomainWordMatrixArgB, aDomainWordMatrixArgC, aDomainWordMatrixArgD);

    TwistExpander_Castor_Arx::SEED_I(PARAMS_SEED);

    TwistExpander_Castor_Arx::SEED_J(PARAMS_SEED);

    TwistDiffuse::DiffuseWithDomainWords(
        aFrostLaneA, aFrostLaneB, aFrostLaneC, aFrostLaneD,  // input lanes
        aArcaneLaneA, aArcaneLaneB, aArcaneLaneC, aArcaneLaneD, // output lanes
        aPlanarLaneA, aPlanarLaneB, aPlanarLaneC, aPlanarLaneD, // entropy lanes
        aIndexList256A, aIndexList256B, aIndexList256C, aIndexList256D, &mMatrix, aDomainWordMatrixSelectA, aDomainWordMatrixSelectB, aDomainWordMatrixUnrollA, aDomainWordMatrixUnrollB, aDomainWordMatrixArgA, aDomainWordMatrixArgB, aDomainWordMatrixArgC, aDomainWordMatrixArgD);

    TwistExpander_Castor_Arx::SEED_K(PARAMS_SEED);

    TwistExpander_Castor_Arx::SEED_L(PARAMS_SEED);

    TwistDiffuse::DiffuseWithDomainWords(
        aRunicLaneA, aRunicLaneB, aRunicLaneC, aRunicLaneD,  // input lanes
        aGloomLaneA, aGloomLaneB, aGloomLaneC, aGloomLaneD, // output lanes
        aLunarLaneA, aLunarLaneB, aLunarLaneC, aLunarLaneD, // entropy lanes
        aIndexList256A, aIndexList256B, aIndexList256C, aIndexList256D, &mMatrix, aDomainWordMatrixSelectA, aDomainWordMatrixSelectB, aDomainWordMatrixUnrollA, aDomainWordMatrixUnrollB, aDomainWordMatrixArgA, aDomainWordMatrixArgB, aDomainWordMatrixArgC, aDomainWordMatrixArgD);

    TwistExpander_Castor_Arx::SEED_M(PARAMS_SEED);

    TwistExpander_Castor_Arx::SEED_N(PARAMS_SEED);

    TwistDiffuse::DiffuseWithDomainWords(
        aDivinationLaneA, aDivinationLaneB, aDivinationLaneC, aDivinationLaneD,  // input lanes
        aEvocationLaneA, aEvocationLaneB, aEvocationLaneC, aEvocationLaneD, // output lanes
        aAbjurationLaneA, aAbjurationLaneB, aAbjurationLaneC, aAbjurationLaneD, // entropy lanes
        aIndexList256A, aIndexList256B, aIndexList256C, aIndexList256D, &mMatrix, aDomainWordMatrixSelectA, aDomainWordMatrixSelectB, aDomainWordMatrixUnrollA, aDomainWordMatrixUnrollB, aDomainWordMatrixArgA, aDomainWordMatrixArgB, aDomainWordMatrixArgC, aDomainWordMatrixArgD);

    TwistExpander_Castor_Arx::SEED_O(PARAMS_SEED);

    TwistExpander_Castor_Arx::SEED_P(PARAMS_SEED);

    TwistDiffuse::DiffuseWithDomainWords(
        aCovenLaneA, aCovenLaneB, aCovenLaneC, aCovenLaneD,  // input lanes
        aHeartLaneA, aHeartLaneB, aHeartLaneC, aHeartLaneD, // output lanes
        aFireLaneA, aFireLaneB, aFireLaneC, aFireLaneD, // entropy lanes
        aIndexList256A, aIndexList256B, aIndexList256C, aIndexList256D, &mMatrix, aDomainWordMatrixSelectA, aDomainWordMatrixSelectB, aDomainWordMatrixUnrollA, aDomainWordMatrixUnrollB, aDomainWordMatrixArgA, aDomainWordMatrixArgB, aDomainWordMatrixArgC, aDomainWordMatrixArgD);

    TwistExpander_Castor_Arx::SEED_Q(PARAMS_SEED);
    //
    ////////////////////////////////////////////////////////

    ////////////////////////////////////////////////////////
    //
    // Independent key-row flows
    //
    // Key flow — A / A

    TwistExpander_Castor_Arx::KEY_A_A_A(PARAMS_SEED);

    TwistExpander_Castor_Arx::KEY_A_A_B(PARAMS_SEED);

    KeyDiffuse_A_A_A(pWorkSpace);

    TwistExpander_Castor_Arx::KEY_A_A_C(PARAMS_SEED);

    TwistExpander_Castor_Arx::KEY_A_A_D(PARAMS_SEED);

    KeyDiffuse_B_A_A(pWorkSpace);

    TwistExpander_Castor_Arx::KEY_A_A_E(PARAMS_SEED);

    TwistSquash::SquashKeyA(CASTOR_KEY_A_A_IceLaneA, CASTOR_KEY_A_A_IceLaneB, CASTOR_KEY_A_A_IceLaneC, CASTOR_KEY_A_A_IceLaneD, &(pWorkSpace->mKeyBoxA[0U][0]));

    // Key flow — A / B

    TwistExpander_Castor_Arx::KEY_A_B_A(PARAMS_SEED);

    TwistExpander_Castor_Arx::KEY_A_B_B(PARAMS_SEED);

    KeyDiffuse_A_A_B(pWorkSpace);

    TwistExpander_Castor_Arx::KEY_A_B_C(PARAMS_SEED);

    TwistExpander_Castor_Arx::KEY_A_B_D(PARAMS_SEED);

    KeyDiffuse_B_A_B(pWorkSpace);

    TwistExpander_Castor_Arx::KEY_A_B_E(PARAMS_SEED);

    TwistSquash::SquashKeyA(CASTOR_KEY_A_B_IceLaneA, CASTOR_KEY_A_B_IceLaneB, CASTOR_KEY_A_B_IceLaneC, CASTOR_KEY_A_B_IceLaneD, &(pWorkSpace->mKeyBoxA[1U][0]));

    // Key flow — A / C

    TwistExpander_Castor_Arx::KEY_A_C_A(PARAMS_SEED);

    TwistExpander_Castor_Arx::KEY_A_C_B(PARAMS_SEED);

    KeyDiffuse_A_A_C(pWorkSpace);

    TwistExpander_Castor_Arx::KEY_A_C_C(PARAMS_SEED);

    TwistExpander_Castor_Arx::KEY_A_C_D(PARAMS_SEED);

    KeyDiffuse_B_A_C(pWorkSpace);

    TwistExpander_Castor_Arx::KEY_A_C_E(PARAMS_SEED);

    TwistSquash::SquashKeyA(CASTOR_KEY_A_C_IceLaneA, CASTOR_KEY_A_C_IceLaneB, CASTOR_KEY_A_C_IceLaneC, CASTOR_KEY_A_C_IceLaneD, &(pWorkSpace->mKeyBoxA[2U][0]));

    // Key flow — A / D

    TwistExpander_Castor_Arx::KEY_A_D_A(PARAMS_SEED);

    TwistExpander_Castor_Arx::KEY_A_D_B(PARAMS_SEED);

    KeyDiffuse_A_A_D(pWorkSpace);

    TwistExpander_Castor_Arx::KEY_A_D_C(PARAMS_SEED);

    TwistExpander_Castor_Arx::KEY_A_D_D(PARAMS_SEED);

    KeyDiffuse_B_A_D(pWorkSpace);

    TwistExpander_Castor_Arx::KEY_A_D_E(PARAMS_SEED);

    TwistSquash::SquashKeyA(CASTOR_KEY_A_D_IceLaneA, CASTOR_KEY_A_D_IceLaneB, CASTOR_KEY_A_D_IceLaneC, CASTOR_KEY_A_D_IceLaneD, &(pWorkSpace->mKeyBoxA[3U][0]));

    // Key flow — A / E

    TwistExpander_Castor_Arx::KEY_A_E_A(PARAMS_SEED);

    TwistExpander_Castor_Arx::KEY_A_E_B(PARAMS_SEED);

    KeyDiffuse_A_A_E(pWorkSpace);

    TwistExpander_Castor_Arx::KEY_A_E_C(PARAMS_SEED);

    TwistExpander_Castor_Arx::KEY_A_E_D(PARAMS_SEED);

    KeyDiffuse_B_A_E(pWorkSpace);

    TwistExpander_Castor_Arx::KEY_A_E_E(PARAMS_SEED);

    TwistSquash::SquashKeyA(CASTOR_KEY_A_E_IceLaneA, CASTOR_KEY_A_E_IceLaneB, CASTOR_KEY_A_E_IceLaneC, CASTOR_KEY_A_E_IceLaneD, &(pWorkSpace->mKeyBoxA[4U][0]));

    // Key flow — A / F

    TwistExpander_Castor_Arx::KEY_A_F_A(PARAMS_SEED);

    TwistExpander_Castor_Arx::KEY_A_F_B(PARAMS_SEED);

    KeyDiffuse_A_A_F(pWorkSpace);

    TwistExpander_Castor_Arx::KEY_A_F_C(PARAMS_SEED);

    TwistExpander_Castor_Arx::KEY_A_F_D(PARAMS_SEED);

    KeyDiffuse_B_A_F(pWorkSpace);

    TwistExpander_Castor_Arx::KEY_A_F_E(PARAMS_SEED);

    TwistSquash::SquashKeyA(CASTOR_KEY_A_F_IceLaneA, CASTOR_KEY_A_F_IceLaneB, CASTOR_KEY_A_F_IceLaneC, CASTOR_KEY_A_F_IceLaneD, &(pWorkSpace->mKeyBoxA[5U][0]));

    // Key flow — A / G

    TwistExpander_Castor_Arx::KEY_A_G_A(PARAMS_SEED);

    TwistExpander_Castor_Arx::KEY_A_G_B(PARAMS_SEED);

    KeyDiffuse_A_A_G(pWorkSpace);

    TwistExpander_Castor_Arx::KEY_A_G_C(PARAMS_SEED);

    TwistExpander_Castor_Arx::KEY_A_G_D(PARAMS_SEED);

    KeyDiffuse_B_A_G(pWorkSpace);

    TwistExpander_Castor_Arx::KEY_A_G_E(PARAMS_SEED);

    TwistSquash::SquashKeyA(CASTOR_KEY_A_G_IceLaneA, CASTOR_KEY_A_G_IceLaneB, CASTOR_KEY_A_G_IceLaneC, CASTOR_KEY_A_G_IceLaneD, &(pWorkSpace->mKeyBoxA[6U][0]));

    // Key flow — A / H

    TwistExpander_Castor_Arx::KEY_A_H_A(PARAMS_SEED);

    TwistExpander_Castor_Arx::KEY_A_H_B(PARAMS_SEED);

    KeyDiffuse_A_A_H(pWorkSpace);

    TwistExpander_Castor_Arx::KEY_A_H_C(PARAMS_SEED);

    TwistExpander_Castor_Arx::KEY_A_H_D(PARAMS_SEED);

    KeyDiffuse_B_A_H(pWorkSpace);

    TwistExpander_Castor_Arx::KEY_A_H_E(PARAMS_SEED);

    TwistSquash::SquashKeyA(CASTOR_KEY_A_H_IceLaneA, CASTOR_KEY_A_H_IceLaneB, CASTOR_KEY_A_H_IceLaneC, CASTOR_KEY_A_H_IceLaneD, &(pWorkSpace->mKeyBoxA[7U][0]));

    // Key flow — B / A

    TwistExpander_Castor_Arx::KEY_B_A_A(PARAMS_SEED);

    TwistExpander_Castor_Arx::KEY_B_A_B(PARAMS_SEED);

    KeyDiffuse_A_B_A(pWorkSpace);

    TwistExpander_Castor_Arx::KEY_B_A_C(PARAMS_SEED);

    TwistExpander_Castor_Arx::KEY_B_A_D(PARAMS_SEED);

    KeyDiffuse_B_B_A(pWorkSpace);

    TwistExpander_Castor_Arx::KEY_B_A_E(PARAMS_SEED);

    TwistSquash::SquashKeyA(CASTOR_KEY_B_A_IceLaneA, CASTOR_KEY_B_A_IceLaneB, CASTOR_KEY_B_A_IceLaneC, CASTOR_KEY_B_A_IceLaneD, &(pWorkSpace->mKeyBoxB[0U][0]));

    // Key flow — B / B

    TwistExpander_Castor_Arx::KEY_B_B_A(PARAMS_SEED);

    TwistExpander_Castor_Arx::KEY_B_B_B(PARAMS_SEED);

    KeyDiffuse_A_B_B(pWorkSpace);

    TwistExpander_Castor_Arx::KEY_B_B_C(PARAMS_SEED);

    TwistExpander_Castor_Arx::KEY_B_B_D(PARAMS_SEED);

    KeyDiffuse_B_B_B(pWorkSpace);

    TwistExpander_Castor_Arx::KEY_B_B_E(PARAMS_SEED);

    TwistSquash::SquashKeyA(CASTOR_KEY_B_B_IceLaneA, CASTOR_KEY_B_B_IceLaneB, CASTOR_KEY_B_B_IceLaneC, CASTOR_KEY_B_B_IceLaneD, &(pWorkSpace->mKeyBoxB[1U][0]));

    // Key flow — B / C

    TwistExpander_Castor_Arx::KEY_B_C_A(PARAMS_SEED);

    TwistExpander_Castor_Arx::KEY_B_C_B(PARAMS_SEED);

    KeyDiffuse_A_B_C(pWorkSpace);

    TwistExpander_Castor_Arx::KEY_B_C_C(PARAMS_SEED);

    TwistExpander_Castor_Arx::KEY_B_C_D(PARAMS_SEED);

    KeyDiffuse_B_B_C(pWorkSpace);

    TwistExpander_Castor_Arx::KEY_B_C_E(PARAMS_SEED);

    TwistSquash::SquashKeyA(CASTOR_KEY_B_C_IceLaneA, CASTOR_KEY_B_C_IceLaneB, CASTOR_KEY_B_C_IceLaneC, CASTOR_KEY_B_C_IceLaneD, &(pWorkSpace->mKeyBoxB[2U][0]));

    // Key flow — B / D

    TwistExpander_Castor_Arx::KEY_B_D_A(PARAMS_SEED);

    TwistExpander_Castor_Arx::KEY_B_D_B(PARAMS_SEED);

    KeyDiffuse_A_B_D(pWorkSpace);

    TwistExpander_Castor_Arx::KEY_B_D_C(PARAMS_SEED);

    TwistExpander_Castor_Arx::KEY_B_D_D(PARAMS_SEED);

    KeyDiffuse_B_B_D(pWorkSpace);

    TwistExpander_Castor_Arx::KEY_B_D_E(PARAMS_SEED);

    TwistSquash::SquashKeyA(CASTOR_KEY_B_D_IceLaneA, CASTOR_KEY_B_D_IceLaneB, CASTOR_KEY_B_D_IceLaneC, CASTOR_KEY_B_D_IceLaneD, &(pWorkSpace->mKeyBoxB[3U][0]));

    // Key flow — B / E

    TwistExpander_Castor_Arx::KEY_B_E_A(PARAMS_SEED);

    TwistExpander_Castor_Arx::KEY_B_E_B(PARAMS_SEED);

    KeyDiffuse_A_B_E(pWorkSpace);

    TwistExpander_Castor_Arx::KEY_B_E_C(PARAMS_SEED);

    TwistExpander_Castor_Arx::KEY_B_E_D(PARAMS_SEED);

    KeyDiffuse_B_B_E(pWorkSpace);

    TwistExpander_Castor_Arx::KEY_B_E_E(PARAMS_SEED);

    TwistSquash::SquashKeyA(CASTOR_KEY_B_E_IceLaneA, CASTOR_KEY_B_E_IceLaneB, CASTOR_KEY_B_E_IceLaneC, CASTOR_KEY_B_E_IceLaneD, &(pWorkSpace->mKeyBoxB[4U][0]));

    // Key flow — B / F

    TwistExpander_Castor_Arx::KEY_B_F_A(PARAMS_SEED);

    TwistExpander_Castor_Arx::KEY_B_F_B(PARAMS_SEED);

    KeyDiffuse_A_B_F(pWorkSpace);

    TwistExpander_Castor_Arx::KEY_B_F_C(PARAMS_SEED);

    TwistExpander_Castor_Arx::KEY_B_F_D(PARAMS_SEED);

    KeyDiffuse_B_B_F(pWorkSpace);

    TwistExpander_Castor_Arx::KEY_B_F_E(PARAMS_SEED);

    TwistSquash::SquashKeyA(CASTOR_KEY_B_F_IceLaneA, CASTOR_KEY_B_F_IceLaneB, CASTOR_KEY_B_F_IceLaneC, CASTOR_KEY_B_F_IceLaneD, &(pWorkSpace->mKeyBoxB[5U][0]));

    // Key flow — B / G

    TwistExpander_Castor_Arx::KEY_B_G_A(PARAMS_SEED);

    TwistExpander_Castor_Arx::KEY_B_G_B(PARAMS_SEED);

    KeyDiffuse_A_B_G(pWorkSpace);

    TwistExpander_Castor_Arx::KEY_B_G_C(PARAMS_SEED);

    TwistExpander_Castor_Arx::KEY_B_G_D(PARAMS_SEED);

    KeyDiffuse_B_B_G(pWorkSpace);

    TwistExpander_Castor_Arx::KEY_B_G_E(PARAMS_SEED);

    TwistSquash::SquashKeyA(CASTOR_KEY_B_G_IceLaneA, CASTOR_KEY_B_G_IceLaneB, CASTOR_KEY_B_G_IceLaneC, CASTOR_KEY_B_G_IceLaneD, &(pWorkSpace->mKeyBoxB[6U][0]));

    // Key flow — B / H

    TwistExpander_Castor_Arx::KEY_B_H_A(PARAMS_SEED);

    TwistExpander_Castor_Arx::KEY_B_H_B(PARAMS_SEED);

    KeyDiffuse_A_B_H(pWorkSpace);

    TwistExpander_Castor_Arx::KEY_B_H_C(PARAMS_SEED);
    TwistExpander_Castor_Arx::KEY_B_H_D(PARAMS_SEED);

    KeyDiffuse_B_B_H(pWorkSpace);

    TwistExpander_Castor_Arx::KEY_B_H_E(PARAMS_SEED);

    TwistSquash::SquashKeyA(CASTOR_KEY_B_H_IceLaneA, CASTOR_KEY_B_H_IceLaneB, CASTOR_KEY_B_H_IceLaneC, CASTOR_KEY_B_H_IceLaneD, &(pWorkSpace->mKeyBoxB[7U][0]));

    //
    ////////////////////////////////////////////////////////

    ////////////////////////////////////////////////////////
    //
    // Folding main seed loops into destination
    //
    TwistSquash::SquashA(pWorkSpace->mAlchemyLaneA, pWorkSpace->mAlchemyLaneB, pWorkSpace->mAlchemyLaneC, pWorkSpace->mAlchemyLaneD, pDestination);
    //
    ////////////////////////////////////////////////////////

    pWorkSpace->Zero_PostSeed();

    Zero_PostSeed();
}

void TwistExpander_Castor::TwistBlock(TwistWorkSpace *pWorkSpace,
                                       std::uint8_t *pSource,
                                       std::uint8_t *pCrossLaneA,
                                       std::uint8_t *pCrossLaneB,
                                       std::uint8_t *pCrossLaneC,
                                       std::uint8_t *pCrossLaneD,
                                       std::uint8_t *pDestination,
                                       bool pStifleKey) {
    if ((pWorkSpace == nullptr) || (pSource == nullptr) ||
        (pCrossLaneA == nullptr) || (pCrossLaneB == nullptr) ||
        (pCrossLaneC == nullptr) || (pCrossLaneD == nullptr) ||
        (pDestination == nullptr)) { return; }
    std::uint8_t *aFireLaneA = pWorkSpace->mFireLaneA;
    std::uint8_t *aFireLaneB = pWorkSpace->mFireLaneB;
    std::uint8_t *aFireLaneC = pWorkSpace->mFireLaneC;
    std::uint8_t *aFireLaneD = pWorkSpace->mFireLaneD;
    std::uint8_t *aEarthLaneA = pWorkSpace->mEarthLaneA;
    std::uint8_t *aEarthLaneB = pWorkSpace->mEarthLaneB;
    std::uint8_t *aEarthLaneC = pWorkSpace->mEarthLaneC;
    std::uint8_t *aEarthLaneD = pWorkSpace->mEarthLaneD;
    std::uint8_t *aWindLaneA = pWorkSpace->mWindLaneA;
    std::uint8_t *aWindLaneB = pWorkSpace->mWindLaneB;
    std::uint8_t *aWindLaneC = pWorkSpace->mWindLaneC;
    std::uint8_t *aWindLaneD = pWorkSpace->mWindLaneD;
    std::size_t *aIndexList256A = pWorkSpace->mIndexList256A;
    std::size_t *aIndexList256B = pWorkSpace->mIndexList256B;
    std::size_t *aIndexList256C = pWorkSpace->mIndexList256C;
    std::size_t *aIndexList256D = pWorkSpace->mIndexList256D;
    std::uint64_t aIngress = 0U; std::uint64_t aCarry = 0U;

    std::uint64_t aWandererA = 0U; std::uint64_t aWandererB = 0U; std::uint64_t aWandererC = 0U; std::uint64_t aWandererD = 0U;
    std::uint64_t aWandererE = 0U; std::uint64_t aWandererF = 0U; std::uint64_t aWandererG = 0U; std::uint64_t aWandererH = 0U;
    std::uint64_t aWandererI = 0U; std::uint64_t aWandererJ = 0U; std::uint64_t aWandererK = 0U;

    aIngress = 0x933951236DA17CB9ULL;
    aCarry = 0xF186895BCF3D97BAULL;
    aWandererA = 0xFBE8ED00959F9F62ULL;
    aWandererB = 0xE6DF68289D6430EDULL;
    aWandererC = 0xA2DA8FD99C2FD113ULL;
    aWandererD = 0xB08D424D5CB2F731ULL;
    aWandererE = 0x9B1919530C98AEE7ULL;
    aWandererF = 0x9B48937E82773F6FULL;
    aWandererG = 0xE9C8C024CF7B50FBULL;
    aWandererH = 0xF73470479C24159AULL;
    aWandererI = 0xA76E90AB1B6F3E4FULL;
    aWandererJ = 0x8624E214C737B9F7ULL;
    aWandererK = 0xEF6A6195BC50E549ULL;

    ////////////////////////////////////////////////////////
    //
    // Main twist loops
    //
    TwistExpander_Castor_Arx::TWIST_A(PARAMS_TWIST);

    TwistExpander_Castor_Arx::TWIST_B(PARAMS_TWIST);

    std::uint64_t aDomainWordMatrixSelectA = pWorkSpace->mDomainBundle.mTwistConstants.mMatrixSelectA;
    std::uint64_t aDomainWordMatrixSelectB = pWorkSpace->mDomainBundle.mTwistConstants.mMatrixSelectB;

    std::uint8_t aDomainWordMatrixUnrollA = pWorkSpace->mDomainBundle.mTwistConstants.mMatrixUnrollA;
    std::uint8_t aDomainWordMatrixUnrollB = pWorkSpace->mDomainBundle.mTwistConstants.mMatrixUnrollB;

    std::uint8_t aDomainWordMatrixArgA = pWorkSpace->mDomainBundle.mTwistConstants.mMatrixArgA;
    std::uint8_t aDomainWordMatrixArgB = pWorkSpace->mDomainBundle.mTwistConstants.mMatrixArgB;
    std::uint8_t aDomainWordMatrixArgC = pWorkSpace->mDomainBundle.mTwistConstants.mMatrixArgC;
    std::uint8_t aDomainWordMatrixArgD = pWorkSpace->mDomainBundle.mTwistConstants.mMatrixArgD;

    TwistDiffuse::DiffuseWithDomainWords(
        aFireLaneA, aFireLaneB, aFireLaneC, aFireLaneD,  // input lanes
        aWindLaneA, aWindLaneB, aWindLaneC, aWindLaneD, // output lanes
        aEarthLaneA, aEarthLaneB, aEarthLaneC, aEarthLaneD, // entropy lanes
        aIndexList256A, aIndexList256B, aIndexList256C, aIndexList256D, &mMatrix, aDomainWordMatrixSelectA, aDomainWordMatrixSelectB, aDomainWordMatrixUnrollA, aDomainWordMatrixUnrollB, aDomainWordMatrixArgA, aDomainWordMatrixArgB, aDomainWordMatrixArgC, aDomainWordMatrixArgD);

    TwistExpander_Castor_Arx::TWIST_C(PARAMS_TWIST);
    //
    ////////////////////////////////////////////////////////

    ////////////////////////////////////////////////////////
    //
    // Folding main twist loops into destination
    //
    TwistSquash::SquashC(pWorkSpace->mWaterLaneA, pWorkSpace->mWaterLaneB, pWorkSpace->mWaterLaneC, pWorkSpace->mWaterLaneD, pDestination);
    //
    ////////////////////////////////////////////////////////

    ////////////////////////////////////////////////////////
    //
    // Key box management
    //
    if (pStifleKey == true) {
        TwistShiftBox::ShiftKeyBoxA(pWorkSpace);
        TwistShiftBox::ShiftKeyBoxB(pWorkSpace);
    } else {
        TwistForkKeyHalfA(pWorkSpace);
        TwistForkKeyHalfB(pWorkSpace);
        
        const std::uint64_t aGrowIngress = aIngress;
        const std::uint64_t aGrowCarry = aCarry;
        const std::uint64_t aGrowWandererA = aWandererA;
        const std::uint64_t aGrowWandererB = aWandererB;
        const std::uint64_t aGrowWandererC = aWandererC;
        const std::uint64_t aGrowWandererD = aWandererD;
        const std::uint64_t aGrowWandererE = aWandererE;
        const std::uint64_t aGrowWandererF = aWandererF;
        const std::uint64_t aGrowWandererG = aWandererG;
        const std::uint64_t aGrowWandererH = aWandererH;
        const std::uint64_t aGrowWandererI = aWandererI;
        const std::uint64_t aGrowWandererJ = aWandererJ;
        const std::uint64_t aGrowWandererK = aWandererK;
        
        GrowKeyA(pWorkSpace, pCrossLaneA, pCrossLaneC, ARX_STATE_VARS);
        
        aIngress = aGrowIngress;
        aCarry = aGrowCarry;
        aWandererA = aGrowWandererA;
        aWandererB = aGrowWandererB;
        aWandererC = aGrowWandererC;
        aWandererD = aGrowWandererD;
        aWandererE = aGrowWandererE;
        aWandererF = aGrowWandererF;
        aWandererG = aGrowWandererG;
        aWandererH = aGrowWandererH;
        aWandererI = aGrowWandererI;
        aWandererJ = aGrowWandererJ;
        aWandererK = aGrowWandererK;
        
        GrowKeyB(pWorkSpace, pCrossLaneB, pCrossLaneD, ARX_STATE_VARS);
        
    }
    //
    ////////////////////////////////////////////////////////
}

void TwistExpander_Castor::GrowKeyA(TwistWorkSpace *pWorkSpace,
                  std::uint8_t *pCrossLaneA,
                  std::uint8_t *pCrossLaneB,
                  MUTABLE_PARAMS) {
    TwistExpander_Castor_Arx::GROW_A_A(PARAMS_GROW);

    TwistExpander_Castor_Arx::GROW_A_B(PARAMS_GROW);

    std::uint64_t aDomainWordMatrixSelectA = pWorkSpace->mDomainBundle.mKeyRotateAConstants.mMatrixSelectA;
    std::uint64_t aDomainWordMatrixSelectB = pWorkSpace->mDomainBundle.mKeyRotateAConstants.mMatrixSelectB;
    std::uint8_t aDomainWordMatrixUnrollA = pWorkSpace->mDomainBundle.mKeyRotateAConstants.mMatrixUnrollA;
    std::uint8_t aDomainWordMatrixUnrollB = pWorkSpace->mDomainBundle.mKeyRotateAConstants.mMatrixUnrollB;
    std::uint8_t aDomainWordMatrixArgA = pWorkSpace->mDomainBundle.mKeyRotateAConstants.mMatrixArgA;
    std::uint8_t aDomainWordMatrixArgB = pWorkSpace->mDomainBundle.mKeyRotateAConstants.mMatrixArgB;
    std::uint8_t aDomainWordMatrixArgC = pWorkSpace->mDomainBundle.mKeyRotateAConstants.mMatrixArgC;
    std::uint8_t aDomainWordMatrixArgD = pWorkSpace->mDomainBundle.mKeyRotateAConstants.mMatrixArgD;

    TwistDiffuse::KeyDiffuseWithDomainWordsA(
        pWorkSpace->mWindLaneA,
        pWorkSpace->mWindLaneB,
        pWorkSpace->mWindLaneC,
        pWorkSpace->mWindLaneD,
        pWorkSpace->mWaterLaneA,
        pWorkSpace->mWaterLaneB,
        pWorkSpace->mWaterLaneC,
        pWorkSpace->mWaterLaneD,
        pWorkSpace->mFireLaneA,
        pWorkSpace->mFireLaneB,
        pWorkSpace->mFireLaneC,
        pWorkSpace->mFireLaneD,
        pWorkSpace->mIndexList256A, pWorkSpace->mIndexList256B,
        pWorkSpace->mIndexList256C, pWorkSpace->mIndexList256D,
        &mMatrix,
        aDomainWordMatrixSelectA, aDomainWordMatrixSelectB,
        aDomainWordMatrixUnrollA, aDomainWordMatrixUnrollB,
        aDomainWordMatrixArgA, aDomainWordMatrixArgB,
        aDomainWordMatrixArgC, aDomainWordMatrixArgD);

    TwistExpander_Castor_Arx::GROW_A_C(PARAMS_GROW);

    TwistExpander_Castor_Arx::GROW_A_D(PARAMS_GROW);

    TwistDiffuse::KeyDiffuseWithDomainWordsA(
        pWorkSpace->mFrostLaneA,
        pWorkSpace->mFrostLaneB,
        pWorkSpace->mFrostLaneC,
        pWorkSpace->mFrostLaneD,
        pWorkSpace->mKineticLaneA,
        pWorkSpace->mKineticLaneB,
        pWorkSpace->mKineticLaneC,
        pWorkSpace->mKineticLaneD,
        pWorkSpace->mSonicLaneA,
        pWorkSpace->mSonicLaneB,
        pWorkSpace->mSonicLaneC,
        pWorkSpace->mSonicLaneD,
        pWorkSpace->mIndexList256A, pWorkSpace->mIndexList256B,
        pWorkSpace->mIndexList256C, pWorkSpace->mIndexList256D,
        &mMatrix,
        aDomainWordMatrixSelectA, aDomainWordMatrixSelectB,
        aDomainWordMatrixUnrollA, aDomainWordMatrixUnrollB,
        aDomainWordMatrixArgA, aDomainWordMatrixArgB,
        aDomainWordMatrixArgC, aDomainWordMatrixArgD);

    TwistExpander_Castor_Arx::GROW_A_E(PARAMS_GROW);

    TwistShiftBox::ShiftKeyBoxA(pWorkSpace);
    TwistSquash::SquashKeyA(
        pWorkSpace->mIceLaneA,
        pWorkSpace->mIceLaneB,
        pWorkSpace->mIceLaneC,
        pWorkSpace->mIceLaneD,
        &(pWorkSpace->mKeyBoxA[0][0]));
}

void TwistExpander_Castor::GrowKeyB(TwistWorkSpace *pWorkSpace,
                  std::uint8_t *pCrossLaneA,
                  std::uint8_t *pCrossLaneB,
                  MUTABLE_PARAMS) {
    TwistExpander_Castor_Arx::GROW_B_A(PARAMS_GROW);

    TwistExpander_Castor_Arx::GROW_B_B(PARAMS_GROW);

    std::uint64_t aDomainWordMatrixSelectA = pWorkSpace->mDomainBundle.mKeyRotateBConstants.mMatrixSelectA;
    std::uint64_t aDomainWordMatrixSelectB = pWorkSpace->mDomainBundle.mKeyRotateBConstants.mMatrixSelectB;
    std::uint8_t aDomainWordMatrixUnrollA = pWorkSpace->mDomainBundle.mKeyRotateBConstants.mMatrixUnrollA;
    std::uint8_t aDomainWordMatrixUnrollB = pWorkSpace->mDomainBundle.mKeyRotateBConstants.mMatrixUnrollB;
    std::uint8_t aDomainWordMatrixArgA = pWorkSpace->mDomainBundle.mKeyRotateBConstants.mMatrixArgA;
    std::uint8_t aDomainWordMatrixArgB = pWorkSpace->mDomainBundle.mKeyRotateBConstants.mMatrixArgB;
    std::uint8_t aDomainWordMatrixArgC = pWorkSpace->mDomainBundle.mKeyRotateBConstants.mMatrixArgC;
    std::uint8_t aDomainWordMatrixArgD = pWorkSpace->mDomainBundle.mKeyRotateBConstants.mMatrixArgD;

    TwistDiffuse::KeyDiffuseWithDomainWordsB(
        pWorkSpace->mWindLaneA,
        pWorkSpace->mWindLaneB,
        pWorkSpace->mWindLaneC,
        pWorkSpace->mWindLaneD,
        pWorkSpace->mWaterLaneA,
        pWorkSpace->mWaterLaneB,
        pWorkSpace->mWaterLaneC,
        pWorkSpace->mWaterLaneD,
        pWorkSpace->mFireLaneA,
        pWorkSpace->mFireLaneB,
        pWorkSpace->mFireLaneC,
        pWorkSpace->mFireLaneD,
        pWorkSpace->mIndexList256A, pWorkSpace->mIndexList256B,
        pWorkSpace->mIndexList256C, pWorkSpace->mIndexList256D,
        &mMatrix,
        aDomainWordMatrixSelectA, aDomainWordMatrixSelectB,
        aDomainWordMatrixUnrollA, aDomainWordMatrixUnrollB,
        aDomainWordMatrixArgA, aDomainWordMatrixArgB,
        aDomainWordMatrixArgC, aDomainWordMatrixArgD);

    TwistExpander_Castor_Arx::GROW_B_C(PARAMS_GROW);

    TwistExpander_Castor_Arx::GROW_B_D(PARAMS_GROW);

    TwistDiffuse::KeyDiffuseWithDomainWordsB(
        pWorkSpace->mFrostLaneA,
        pWorkSpace->mFrostLaneB,
        pWorkSpace->mFrostLaneC,
        pWorkSpace->mFrostLaneD,
        pWorkSpace->mKineticLaneA,
        pWorkSpace->mKineticLaneB,
        pWorkSpace->mKineticLaneC,
        pWorkSpace->mKineticLaneD,
        pWorkSpace->mSonicLaneA,
        pWorkSpace->mSonicLaneB,
        pWorkSpace->mSonicLaneC,
        pWorkSpace->mSonicLaneD,
        pWorkSpace->mIndexList256A, pWorkSpace->mIndexList256B,
        pWorkSpace->mIndexList256C, pWorkSpace->mIndexList256D,
        &mMatrix,
        aDomainWordMatrixSelectA, aDomainWordMatrixSelectB,
        aDomainWordMatrixUnrollA, aDomainWordMatrixUnrollB,
        aDomainWordMatrixArgA, aDomainWordMatrixArgB,
        aDomainWordMatrixArgC, aDomainWordMatrixArgD);

    TwistExpander_Castor_Arx::GROW_B_E(PARAMS_GROW);

    TwistShiftBox::ShiftKeyBoxB(pWorkSpace);
    TwistSquash::SquashKeyA(
        pWorkSpace->mIceLaneA + (W_KEY * 1U),
        pWorkSpace->mIceLaneB + (W_KEY * 1U),
        pWorkSpace->mIceLaneC + (W_KEY * 1U),
        pWorkSpace->mIceLaneD + (W_KEY * 1U),
        &(pWorkSpace->mKeyBoxB[0][0]));
}

void TwistExpander_Castor::TwistForkKeyHalfA(TwistWorkSpace *pWorkSpace) {
    static_assert(S_BLOCK == 32768, "Twist fork source size changed.");
    static_assert(S_HALF == 16384, "Twist fork half size changed.");
    static_assert(W_KEY == 2048, "Twist fork key size changed.");

    std::uint8_t *aSourceLaneA = pWorkSpace->mWaterLaneA;
    std::uint8_t *aSourceLaneB = pWorkSpace->mWaterLaneB;
    std::uint8_t *aSourceLaneC = pWorkSpace->mWaterLaneC;
    std::uint8_t *aSourceLaneD = pWorkSpace->mWaterLaneD;

    std::uint8_t *aStageOneLaneA = pWorkSpace->mPlanarLaneA;
    std::uint8_t *aStageOneLaneB = pWorkSpace->mPlanarLaneB;
    std::uint8_t *aStageOneLaneC = pWorkSpace->mPlanarLaneC;
    std::uint8_t *aStageOneLaneD = pWorkSpace->mPlanarLaneD;

    std::uint8_t *aStageTwoLaneA = pWorkSpace->mArcaneLaneA;
    std::uint8_t *aStageTwoLaneB = pWorkSpace->mArcaneLaneB;
    std::uint8_t *aStageTwoLaneC = pWorkSpace->mArcaneLaneC;
    std::uint8_t *aStageTwoLaneD = pWorkSpace->mArcaneLaneD;

    // Fold Stage I — 4 x 16,384 bytes into 4 x 8,192 bytes.

    // Destination A, block 0: source B half 0 block 1 + source D half 1 block 7
    for (std::size_t aIndex = 0U; aIndex < W_KEY; ++aIndex) {
        const std::size_t aSourceIndexA = 0U * S_HALF + 1U * W_KEY + ((aIndex + 899U) & W_KEY1);
        const std::size_t aSourceIndexB = 1U * S_HALF + 7U * W_KEY + ((aIndex + 854U) & W_KEY1);
        const std::size_t aDestinationIndex = 0U * (S_HALF >> 1U) + 0U * W_KEY + aIndex;

        std::uint16_t aFoldValue = 0U;
        aFoldValue |= static_cast<std::uint16_t>(aSourceLaneB[aSourceIndexA]) << 0U;
        aFoldValue |= static_cast<std::uint16_t>(aSourceLaneD[aSourceIndexB]) << 8U;
        aFoldValue = TwistMix16::DiffuseA(aFoldValue);

        aStageOneLaneA[aDestinationIndex] = static_cast<std::uint8_t>(aFoldValue >> 0U);
    }

    // Destination A, block 1: source A half 0 block 6 + source B half 0 block 2
    for (std::size_t aIndex = 0U; aIndex < W_KEY; ++aIndex) {
        const std::size_t aSourceIndexA = 0U * S_HALF + 6U * W_KEY + ((aIndex + 809U) & W_KEY1);
        const std::size_t aSourceIndexB = 0U * S_HALF + 2U * W_KEY + ((aIndex + 764U) & W_KEY1);
        const std::size_t aDestinationIndex = 0U * (S_HALF >> 1U) + 1U * W_KEY + aIndex;

        std::uint16_t aFoldValue = 0U;
        aFoldValue |= static_cast<std::uint16_t>(aSourceLaneA[aSourceIndexA]) << 8U;
        aFoldValue |= static_cast<std::uint16_t>(aSourceLaneB[aSourceIndexB]) << 0U;
        aFoldValue = TwistMix16::DiffuseA(aFoldValue);

        aStageOneLaneA[aDestinationIndex] = static_cast<std::uint8_t>(aFoldValue >> 0U);
    }

    // Destination A, block 2: source C half 1 block 4 + source A half 0 block 7
    for (std::size_t aIndex = 0U; aIndex < W_KEY; ++aIndex) {
        const std::size_t aSourceIndexA = 1U * S_HALF + 4U * W_KEY + ((aIndex + 719U) & W_KEY1);
        const std::size_t aSourceIndexB = 0U * S_HALF + 7U * W_KEY + ((aIndex + 674U) & W_KEY1);
        const std::size_t aDestinationIndex = 0U * (S_HALF >> 1U) + 2U * W_KEY + aIndex;

        std::uint16_t aFoldValue = 0U;
        aFoldValue |= static_cast<std::uint16_t>(aSourceLaneC[aSourceIndexA]) << 8U;
        aFoldValue |= static_cast<std::uint16_t>(aSourceLaneA[aSourceIndexB]) << 0U;
        aFoldValue = TwistMix16::DiffuseA(aFoldValue);

        aStageOneLaneA[aDestinationIndex] = static_cast<std::uint8_t>(aFoldValue >> 8U);
    }

    // Destination A, block 3: source D half 1 block 0 + source C half 1 block 5
    for (std::size_t aIndex = 0U; aIndex < W_KEY; ++aIndex) {
        const std::size_t aSourceIndexA = 1U * S_HALF + 0U * W_KEY + ((aIndex + 629U) & W_KEY1);
        const std::size_t aSourceIndexB = 1U * S_HALF + 5U * W_KEY + ((aIndex + 584U) & W_KEY1);
        const std::size_t aDestinationIndex = 0U * (S_HALF >> 1U) + 3U * W_KEY + aIndex;

        std::uint16_t aFoldValue = 0U;
        aFoldValue |= static_cast<std::uint16_t>(aSourceLaneD[aSourceIndexA]) << 8U;
        aFoldValue |= static_cast<std::uint16_t>(aSourceLaneC[aSourceIndexB]) << 0U;
        aFoldValue = TwistMix16::DiffuseA(aFoldValue);

        aStageOneLaneA[aDestinationIndex] = static_cast<std::uint8_t>(aFoldValue >> 8U);
    }

    // Destination B, block 0: source D half 1 block 1 + source C half 1 block 6
    for (std::size_t aIndex = 0U; aIndex < W_KEY; ++aIndex) {
        const std::size_t aSourceIndexA = 1U * S_HALF + 1U * W_KEY + ((aIndex + 539U) & W_KEY1);
        const std::size_t aSourceIndexB = 1U * S_HALF + 6U * W_KEY + ((aIndex + 494U) & W_KEY1);
        const std::size_t aDestinationIndex = 0U * (S_HALF >> 1U) + 0U * W_KEY + aIndex;

        std::uint16_t aFoldValue = 0U;
        aFoldValue |= static_cast<std::uint16_t>(aSourceLaneD[aSourceIndexA]) << 8U;
        aFoldValue |= static_cast<std::uint16_t>(aSourceLaneC[aSourceIndexB]) << 0U;
        aFoldValue = TwistMix16::DiffuseA(aFoldValue);

        aStageOneLaneB[aDestinationIndex] = static_cast<std::uint8_t>(aFoldValue >> 8U);
    }

    // Destination B, block 1: source C half 1 block 7 + source A half 0 block 0
    for (std::size_t aIndex = 0U; aIndex < W_KEY; ++aIndex) {
        const std::size_t aSourceIndexA = 1U * S_HALF + 7U * W_KEY + ((aIndex + 449U) & W_KEY1);
        const std::size_t aSourceIndexB = 0U * S_HALF + 0U * W_KEY + ((aIndex + 404U) & W_KEY1);
        const std::size_t aDestinationIndex = 0U * (S_HALF >> 1U) + 1U * W_KEY + aIndex;

        std::uint16_t aFoldValue = 0U;
        aFoldValue |= static_cast<std::uint16_t>(aSourceLaneC[aSourceIndexA]) << 0U;
        aFoldValue |= static_cast<std::uint16_t>(aSourceLaneA[aSourceIndexB]) << 8U;
        aFoldValue = TwistMix16::DiffuseA(aFoldValue);

        aStageOneLaneB[aDestinationIndex] = static_cast<std::uint8_t>(aFoldValue >> 0U);
    }

    // Destination B, block 2: source A half 0 block 1 + source B half 0 block 3
    for (std::size_t aIndex = 0U; aIndex < W_KEY; ++aIndex) {
        const std::size_t aSourceIndexA = 0U * S_HALF + 1U * W_KEY + ((aIndex + 359U) & W_KEY1);
        const std::size_t aSourceIndexB = 0U * S_HALF + 3U * W_KEY + ((aIndex + 314U) & W_KEY1);
        const std::size_t aDestinationIndex = 0U * (S_HALF >> 1U) + 2U * W_KEY + aIndex;

        std::uint16_t aFoldValue = 0U;
        aFoldValue |= static_cast<std::uint16_t>(aSourceLaneA[aSourceIndexA]) << 0U;
        aFoldValue |= static_cast<std::uint16_t>(aSourceLaneB[aSourceIndexB]) << 8U;
        aFoldValue = TwistMix16::DiffuseA(aFoldValue);

        aStageOneLaneB[aDestinationIndex] = static_cast<std::uint8_t>(aFoldValue >> 8U);
    }

    // Destination B, block 3: source B half 0 block 4 + source D half 1 block 2
    for (std::size_t aIndex = 0U; aIndex < W_KEY; ++aIndex) {
        const std::size_t aSourceIndexA = 0U * S_HALF + 4U * W_KEY + ((aIndex + 269U) & W_KEY1);
        const std::size_t aSourceIndexB = 1U * S_HALF + 2U * W_KEY + ((aIndex + 224U) & W_KEY1);
        const std::size_t aDestinationIndex = 0U * (S_HALF >> 1U) + 3U * W_KEY + aIndex;

        std::uint16_t aFoldValue = 0U;
        aFoldValue |= static_cast<std::uint16_t>(aSourceLaneB[aSourceIndexA]) << 0U;
        aFoldValue |= static_cast<std::uint16_t>(aSourceLaneD[aSourceIndexB]) << 8U;
        aFoldValue = TwistMix16::DiffuseA(aFoldValue);

        aStageOneLaneB[aDestinationIndex] = static_cast<std::uint8_t>(aFoldValue >> 0U);
    }

    // Destination C, block 0: source A half 0 block 2 + source D half 1 block 3
    for (std::size_t aIndex = 0U; aIndex < W_KEY; ++aIndex) {
        const std::size_t aSourceIndexA = 0U * S_HALF + 2U * W_KEY + ((aIndex + 179U) & W_KEY1);
        const std::size_t aSourceIndexB = 1U * S_HALF + 3U * W_KEY + ((aIndex + 134U) & W_KEY1);
        const std::size_t aDestinationIndex = 0U * (S_HALF >> 1U) + 0U * W_KEY + aIndex;

        std::uint16_t aFoldValue = 0U;
        aFoldValue |= static_cast<std::uint16_t>(aSourceLaneA[aSourceIndexA]) << 0U;
        aFoldValue |= static_cast<std::uint16_t>(aSourceLaneD[aSourceIndexB]) << 8U;
        aFoldValue = TwistMix16::DiffuseA(aFoldValue);

        aStageOneLaneC[aDestinationIndex] = static_cast<std::uint8_t>(aFoldValue >> 8U);
    }

    // Destination C, block 1: source B half 0 block 5 + source A half 0 block 3
    for (std::size_t aIndex = 0U; aIndex < W_KEY; ++aIndex) {
        const std::size_t aSourceIndexA = 0U * S_HALF + 5U * W_KEY + ((aIndex + 89U) & W_KEY1);
        const std::size_t aSourceIndexB = 0U * S_HALF + 3U * W_KEY + ((aIndex + 44U) & W_KEY1);
        const std::size_t aDestinationIndex = 0U * (S_HALF >> 1U) + 1U * W_KEY + aIndex;

        std::uint16_t aFoldValue = 0U;
        aFoldValue |= static_cast<std::uint16_t>(aSourceLaneB[aSourceIndexA]) << 8U;
        aFoldValue |= static_cast<std::uint16_t>(aSourceLaneA[aSourceIndexB]) << 0U;
        aFoldValue = TwistMix16::DiffuseA(aFoldValue);

        aStageOneLaneC[aDestinationIndex] = static_cast<std::uint8_t>(aFoldValue >> 0U);
    }

    // Destination C, block 2: source C half 1 block 0 + source B half 0 block 6
    for (std::size_t aIndex = 0U; aIndex < W_KEY; ++aIndex) {
        const std::size_t aSourceIndexA = 1U * S_HALF + 0U * W_KEY + ((aIndex + 2047U) & W_KEY1);
        const std::size_t aSourceIndexB = 0U * S_HALF + 6U * W_KEY + ((aIndex + 2002U) & W_KEY1);
        const std::size_t aDestinationIndex = 0U * (S_HALF >> 1U) + 2U * W_KEY + aIndex;

        std::uint16_t aFoldValue = 0U;
        aFoldValue |= static_cast<std::uint16_t>(aSourceLaneC[aSourceIndexA]) << 8U;
        aFoldValue |= static_cast<std::uint16_t>(aSourceLaneB[aSourceIndexB]) << 0U;
        aFoldValue = TwistMix16::DiffuseA(aFoldValue);

        aStageOneLaneC[aDestinationIndex] = static_cast<std::uint8_t>(aFoldValue >> 0U);
    }

    // Destination C, block 3: source D half 1 block 4 + source C half 1 block 1
    for (std::size_t aIndex = 0U; aIndex < W_KEY; ++aIndex) {
        const std::size_t aSourceIndexA = 1U * S_HALF + 4U * W_KEY + ((aIndex + 1957U) & W_KEY1);
        const std::size_t aSourceIndexB = 1U * S_HALF + 1U * W_KEY + ((aIndex + 1912U) & W_KEY1);
        const std::size_t aDestinationIndex = 0U * (S_HALF >> 1U) + 3U * W_KEY + aIndex;

        std::uint16_t aFoldValue = 0U;
        aFoldValue |= static_cast<std::uint16_t>(aSourceLaneD[aSourceIndexA]) << 8U;
        aFoldValue |= static_cast<std::uint16_t>(aSourceLaneC[aSourceIndexB]) << 0U;
        aFoldValue = TwistMix16::DiffuseA(aFoldValue);

        aStageOneLaneC[aDestinationIndex] = static_cast<std::uint8_t>(aFoldValue >> 8U);
    }

    // Destination D, block 0: source A half 0 block 4 + source D half 1 block 5
    for (std::size_t aIndex = 0U; aIndex < W_KEY; ++aIndex) {
        const std::size_t aSourceIndexA = 0U * S_HALF + 4U * W_KEY + ((aIndex + 1867U) & W_KEY1);
        const std::size_t aSourceIndexB = 1U * S_HALF + 5U * W_KEY + ((aIndex + 1822U) & W_KEY1);
        const std::size_t aDestinationIndex = 0U * (S_HALF >> 1U) + 0U * W_KEY + aIndex;

        std::uint16_t aFoldValue = 0U;
        aFoldValue |= static_cast<std::uint16_t>(aSourceLaneA[aSourceIndexA]) << 8U;
        aFoldValue |= static_cast<std::uint16_t>(aSourceLaneD[aSourceIndexB]) << 0U;
        aFoldValue = TwistMix16::DiffuseA(aFoldValue);

        aStageOneLaneD[aDestinationIndex] = static_cast<std::uint8_t>(aFoldValue >> 0U);
    }

    // Destination D, block 1: source D half 1 block 6 + source B half 0 block 7
    for (std::size_t aIndex = 0U; aIndex < W_KEY; ++aIndex) {
        const std::size_t aSourceIndexA = 1U * S_HALF + 6U * W_KEY + ((aIndex + 1777U) & W_KEY1);
        const std::size_t aSourceIndexB = 0U * S_HALF + 7U * W_KEY + ((aIndex + 1732U) & W_KEY1);
        const std::size_t aDestinationIndex = 0U * (S_HALF >> 1U) + 1U * W_KEY + aIndex;

        std::uint16_t aFoldValue = 0U;
        aFoldValue |= static_cast<std::uint16_t>(aSourceLaneD[aSourceIndexA]) << 0U;
        aFoldValue |= static_cast<std::uint16_t>(aSourceLaneB[aSourceIndexB]) << 8U;
        aFoldValue = TwistMix16::DiffuseA(aFoldValue);

        aStageOneLaneD[aDestinationIndex] = static_cast<std::uint8_t>(aFoldValue >> 8U);
    }

    // Destination D, block 2: source B half 0 block 0 + source C half 1 block 2
    for (std::size_t aIndex = 0U; aIndex < W_KEY; ++aIndex) {
        const std::size_t aSourceIndexA = 0U * S_HALF + 0U * W_KEY + ((aIndex + 1687U) & W_KEY1);
        const std::size_t aSourceIndexB = 1U * S_HALF + 2U * W_KEY + ((aIndex + 1642U) & W_KEY1);
        const std::size_t aDestinationIndex = 0U * (S_HALF >> 1U) + 2U * W_KEY + aIndex;

        std::uint16_t aFoldValue = 0U;
        aFoldValue |= static_cast<std::uint16_t>(aSourceLaneB[aSourceIndexA]) << 0U;
        aFoldValue |= static_cast<std::uint16_t>(aSourceLaneC[aSourceIndexB]) << 8U;
        aFoldValue = TwistMix16::DiffuseA(aFoldValue);

        aStageOneLaneD[aDestinationIndex] = static_cast<std::uint8_t>(aFoldValue >> 8U);
    }

    // Destination D, block 3: source C half 1 block 3 + source A half 0 block 5
    for (std::size_t aIndex = 0U; aIndex < W_KEY; ++aIndex) {
        const std::size_t aSourceIndexA = 1U * S_HALF + 3U * W_KEY + ((aIndex + 1597U) & W_KEY1);
        const std::size_t aSourceIndexB = 0U * S_HALF + 5U * W_KEY + ((aIndex + 1552U) & W_KEY1);
        const std::size_t aDestinationIndex = 0U * (S_HALF >> 1U) + 3U * W_KEY + aIndex;

        std::uint16_t aFoldValue = 0U;
        aFoldValue |= static_cast<std::uint16_t>(aSourceLaneC[aSourceIndexA]) << 0U;
        aFoldValue |= static_cast<std::uint16_t>(aSourceLaneA[aSourceIndexB]) << 8U;
        aFoldValue = TwistMix16::DiffuseA(aFoldValue);

        aStageOneLaneD[aDestinationIndex] = static_cast<std::uint8_t>(aFoldValue >> 0U);
    }

    // Fold Stage II — 4 x 8,192 bytes into 4 x W_KEY bytes.

    // Key piece A
    for (std::size_t aIndex = 0U; aIndex < W_KEY; ++aIndex) {
        const std::size_t aSourceIndexA = 0U * (S_HALF >> 1U) + 1U * W_KEY + ((aIndex + 1673U) & W_KEY1);
        const std::size_t aSourceIndexB = 0U * (S_HALF >> 1U) + 1U * W_KEY + ((aIndex + 1628U) & W_KEY1);
        const std::size_t aSourceIndexC = 0U * (S_HALF >> 1U) + 2U * W_KEY + ((aIndex + 1583U) & W_KEY1);
        const std::size_t aSourceIndexD = 0U * (S_HALF >> 1U) + 3U * W_KEY + ((aIndex + 1538U) & W_KEY1);
        const std::size_t aDestinationIndex = 0U * W_KEY + aIndex;

        std::uint32_t aFoldValue = 0U;
        aFoldValue |= static_cast<std::uint32_t>(aStageOneLaneA[aSourceIndexA]) << 8U;
        aFoldValue |= static_cast<std::uint32_t>(aStageOneLaneB[aSourceIndexB]) << 0U;
        aFoldValue |= static_cast<std::uint32_t>(aStageOneLaneC[aSourceIndexC]) << 16U;
        aFoldValue |= static_cast<std::uint32_t>(aStageOneLaneD[aSourceIndexD]) << 24U;
        aFoldValue = TwistMix32::DiffuseA(aFoldValue);

        aStageTwoLaneA[aDestinationIndex] = static_cast<std::uint8_t>(aFoldValue >> 24U);
    }

    // Key piece B
    for (std::size_t aIndex = 0U; aIndex < W_KEY; ++aIndex) {
        const std::size_t aSourceIndexA = 0U * (S_HALF >> 1U) + 0U * W_KEY + ((aIndex + 1493U) & W_KEY1);
        const std::size_t aSourceIndexB = 0U * (S_HALF >> 1U) + 3U * W_KEY + ((aIndex + 1448U) & W_KEY1);
        const std::size_t aSourceIndexC = 0U * (S_HALF >> 1U) + 3U * W_KEY + ((aIndex + 1403U) & W_KEY1);
        const std::size_t aSourceIndexD = 0U * (S_HALF >> 1U) + 1U * W_KEY + ((aIndex + 1358U) & W_KEY1);
        const std::size_t aDestinationIndex = 0U * W_KEY + aIndex;

        std::uint32_t aFoldValue = 0U;
        aFoldValue |= static_cast<std::uint32_t>(aStageOneLaneA[aSourceIndexA]) << 16U;
        aFoldValue |= static_cast<std::uint32_t>(aStageOneLaneB[aSourceIndexB]) << 0U;
        aFoldValue |= static_cast<std::uint32_t>(aStageOneLaneC[aSourceIndexC]) << 24U;
        aFoldValue |= static_cast<std::uint32_t>(aStageOneLaneD[aSourceIndexD]) << 8U;
        aFoldValue = TwistMix32::DiffuseA(aFoldValue);

        aStageTwoLaneB[aDestinationIndex] = static_cast<std::uint8_t>(aFoldValue >> 0U);
    }

    // Key piece C
    for (std::size_t aIndex = 0U; aIndex < W_KEY; ++aIndex) {
        const std::size_t aSourceIndexA = 0U * (S_HALF >> 1U) + 2U * W_KEY + ((aIndex + 1313U) & W_KEY1);
        const std::size_t aSourceIndexB = 0U * (S_HALF >> 1U) + 2U * W_KEY + ((aIndex + 1268U) & W_KEY1);
        const std::size_t aSourceIndexC = 0U * (S_HALF >> 1U) + 0U * W_KEY + ((aIndex + 1223U) & W_KEY1);
        const std::size_t aSourceIndexD = 0U * (S_HALF >> 1U) + 2U * W_KEY + ((aIndex + 1178U) & W_KEY1);
        const std::size_t aDestinationIndex = 0U * W_KEY + aIndex;

        std::uint32_t aFoldValue = 0U;
        aFoldValue |= static_cast<std::uint32_t>(aStageOneLaneA[aSourceIndexA]) << 24U;
        aFoldValue |= static_cast<std::uint32_t>(aStageOneLaneB[aSourceIndexB]) << 8U;
        aFoldValue |= static_cast<std::uint32_t>(aStageOneLaneC[aSourceIndexC]) << 0U;
        aFoldValue |= static_cast<std::uint32_t>(aStageOneLaneD[aSourceIndexD]) << 16U;
        aFoldValue = TwistMix32::DiffuseA(aFoldValue);

        aStageTwoLaneC[aDestinationIndex] = static_cast<std::uint8_t>(aFoldValue >> 8U);
    }

    // Key piece D
    for (std::size_t aIndex = 0U; aIndex < W_KEY; ++aIndex) {
        const std::size_t aSourceIndexA = 0U * (S_HALF >> 1U) + 3U * W_KEY + ((aIndex + 1133U) & W_KEY1);
        const std::size_t aSourceIndexB = 0U * (S_HALF >> 1U) + 0U * W_KEY + ((aIndex + 1088U) & W_KEY1);
        const std::size_t aSourceIndexC = 0U * (S_HALF >> 1U) + 1U * W_KEY + ((aIndex + 1043U) & W_KEY1);
        const std::size_t aSourceIndexD = 0U * (S_HALF >> 1U) + 0U * W_KEY + ((aIndex + 998U) & W_KEY1);
        const std::size_t aDestinationIndex = 0U * W_KEY + aIndex;

        std::uint32_t aFoldValue = 0U;
        aFoldValue |= static_cast<std::uint32_t>(aStageOneLaneA[aSourceIndexA]) << 0U;
        aFoldValue |= static_cast<std::uint32_t>(aStageOneLaneB[aSourceIndexB]) << 16U;
        aFoldValue |= static_cast<std::uint32_t>(aStageOneLaneC[aSourceIndexC]) << 24U;
        aFoldValue |= static_cast<std::uint32_t>(aStageOneLaneD[aSourceIndexD]) << 8U;
        aFoldValue = TwistMix32::DiffuseA(aFoldValue);

        aStageTwoLaneD[aDestinationIndex] = static_cast<std::uint8_t>(aFoldValue >> 16U);
    }
}

void TwistExpander_Castor::TwistForkKeyHalfB(TwistWorkSpace *pWorkSpace) {
    static_assert(S_BLOCK == 32768, "Twist fork source size changed.");
    static_assert(S_HALF == 16384, "Twist fork half size changed.");
    static_assert(W_KEY == 2048, "Twist fork key size changed.");

    std::uint8_t *aSourceLaneA = pWorkSpace->mWaterLaneA;
    std::uint8_t *aSourceLaneB = pWorkSpace->mWaterLaneB;
    std::uint8_t *aSourceLaneC = pWorkSpace->mWaterLaneC;
    std::uint8_t *aSourceLaneD = pWorkSpace->mWaterLaneD;

    std::uint8_t *aStageOneLaneA = pWorkSpace->mPlanarLaneA;
    std::uint8_t *aStageOneLaneB = pWorkSpace->mPlanarLaneB;
    std::uint8_t *aStageOneLaneC = pWorkSpace->mPlanarLaneC;
    std::uint8_t *aStageOneLaneD = pWorkSpace->mPlanarLaneD;

    std::uint8_t *aStageTwoLaneA = pWorkSpace->mRunicLaneA;
    std::uint8_t *aStageTwoLaneB = pWorkSpace->mRunicLaneB;
    std::uint8_t *aStageTwoLaneC = pWorkSpace->mRunicLaneC;
    std::uint8_t *aStageTwoLaneD = pWorkSpace->mRunicLaneD;

    // Fold Stage I — 4 x 16,384 bytes into 4 x 8,192 bytes.

    // Destination A, block 0: source D half 0 block 0 + source B half 1 block 2
    for (std::size_t aIndex = 0U; aIndex < W_KEY; ++aIndex) {
        const std::size_t aSourceIndexA = 0U * S_HALF + 0U * W_KEY + ((aIndex + 1507U) & W_KEY1);
        const std::size_t aSourceIndexB = 1U * S_HALF + 2U * W_KEY + ((aIndex + 1462U) & W_KEY1);
        const std::size_t aDestinationIndex = 1U * (S_HALF >> 1U) + 0U * W_KEY + aIndex;

        std::uint16_t aFoldValue = 0U;
        aFoldValue |= static_cast<std::uint16_t>(aSourceLaneD[aSourceIndexA]) << 8U;
        aFoldValue |= static_cast<std::uint16_t>(aSourceLaneB[aSourceIndexB]) << 0U;
        aFoldValue = TwistMix16::DiffuseA(aFoldValue);

        aStageOneLaneA[aDestinationIndex] = static_cast<std::uint8_t>(aFoldValue >> 8U);
    }

    // Destination A, block 1: source B half 1 block 5 + source A half 1 block 7
    for (std::size_t aIndex = 0U; aIndex < W_KEY; ++aIndex) {
        const std::size_t aSourceIndexA = 1U * S_HALF + 5U * W_KEY + ((aIndex + 1417U) & W_KEY1);
        const std::size_t aSourceIndexB = 1U * S_HALF + 7U * W_KEY + ((aIndex + 1372U) & W_KEY1);
        const std::size_t aDestinationIndex = 1U * (S_HALF >> 1U) + 1U * W_KEY + aIndex;

        std::uint16_t aFoldValue = 0U;
        aFoldValue |= static_cast<std::uint16_t>(aSourceLaneB[aSourceIndexA]) << 8U;
        aFoldValue |= static_cast<std::uint16_t>(aSourceLaneA[aSourceIndexB]) << 0U;
        aFoldValue = TwistMix16::DiffuseA(aFoldValue);

        aStageOneLaneA[aDestinationIndex] = static_cast<std::uint8_t>(aFoldValue >> 0U);
    }

    // Destination A, block 2: source A half 1 block 2 + source C half 0 block 5
    for (std::size_t aIndex = 0U; aIndex < W_KEY; ++aIndex) {
        const std::size_t aSourceIndexA = 1U * S_HALF + 2U * W_KEY + ((aIndex + 1327U) & W_KEY1);
        const std::size_t aSourceIndexB = 0U * S_HALF + 5U * W_KEY + ((aIndex + 1282U) & W_KEY1);
        const std::size_t aDestinationIndex = 1U * (S_HALF >> 1U) + 2U * W_KEY + aIndex;

        std::uint16_t aFoldValue = 0U;
        aFoldValue |= static_cast<std::uint16_t>(aSourceLaneA[aSourceIndexA]) << 8U;
        aFoldValue |= static_cast<std::uint16_t>(aSourceLaneC[aSourceIndexB]) << 0U;
        aFoldValue = TwistMix16::DiffuseA(aFoldValue);

        aStageOneLaneA[aDestinationIndex] = static_cast<std::uint8_t>(aFoldValue >> 8U);
    }

    // Destination A, block 3: source C half 0 block 0 + source D half 0 block 3
    for (std::size_t aIndex = 0U; aIndex < W_KEY; ++aIndex) {
        const std::size_t aSourceIndexA = 0U * S_HALF + 0U * W_KEY + ((aIndex + 1237U) & W_KEY1);
        const std::size_t aSourceIndexB = 0U * S_HALF + 3U * W_KEY + ((aIndex + 1192U) & W_KEY1);
        const std::size_t aDestinationIndex = 1U * (S_HALF >> 1U) + 3U * W_KEY + aIndex;

        std::uint16_t aFoldValue = 0U;
        aFoldValue |= static_cast<std::uint16_t>(aSourceLaneC[aSourceIndexA]) << 8U;
        aFoldValue |= static_cast<std::uint16_t>(aSourceLaneD[aSourceIndexB]) << 0U;
        aFoldValue = TwistMix16::DiffuseA(aFoldValue);

        aStageOneLaneA[aDestinationIndex] = static_cast<std::uint8_t>(aFoldValue >> 0U);
    }

    // Destination B, block 0: source A half 1 block 5 + source C half 0 block 3
    for (std::size_t aIndex = 0U; aIndex < W_KEY; ++aIndex) {
        const std::size_t aSourceIndexA = 1U * S_HALF + 5U * W_KEY + ((aIndex + 1147U) & W_KEY1);
        const std::size_t aSourceIndexB = 0U * S_HALF + 3U * W_KEY + ((aIndex + 1102U) & W_KEY1);
        const std::size_t aDestinationIndex = 1U * (S_HALF >> 1U) + 0U * W_KEY + aIndex;

        std::uint16_t aFoldValue = 0U;
        aFoldValue |= static_cast<std::uint16_t>(aSourceLaneA[aSourceIndexA]) << 0U;
        aFoldValue |= static_cast<std::uint16_t>(aSourceLaneC[aSourceIndexB]) << 8U;
        aFoldValue = TwistMix16::DiffuseA(aFoldValue);

        aStageOneLaneB[aDestinationIndex] = static_cast<std::uint8_t>(aFoldValue >> 0U);
    }

    // Destination B, block 1: source B half 1 block 0 + source A half 1 block 0
    for (std::size_t aIndex = 0U; aIndex < W_KEY; ++aIndex) {
        const std::size_t aSourceIndexA = 1U * S_HALF + 0U * W_KEY + ((aIndex + 1057U) & W_KEY1);
        const std::size_t aSourceIndexB = 1U * S_HALF + 0U * W_KEY + ((aIndex + 1012U) & W_KEY1);
        const std::size_t aDestinationIndex = 1U * (S_HALF >> 1U) + 1U * W_KEY + aIndex;

        std::uint16_t aFoldValue = 0U;
        aFoldValue |= static_cast<std::uint16_t>(aSourceLaneB[aSourceIndexA]) << 0U;
        aFoldValue |= static_cast<std::uint16_t>(aSourceLaneA[aSourceIndexB]) << 8U;
        aFoldValue = TwistMix16::DiffuseA(aFoldValue);

        aStageOneLaneB[aDestinationIndex] = static_cast<std::uint8_t>(aFoldValue >> 8U);
    }

    // Destination B, block 2: source D half 0 block 6 + source B half 1 block 3
    for (std::size_t aIndex = 0U; aIndex < W_KEY; ++aIndex) {
        const std::size_t aSourceIndexA = 0U * S_HALF + 6U * W_KEY + ((aIndex + 967U) & W_KEY1);
        const std::size_t aSourceIndexB = 1U * S_HALF + 3U * W_KEY + ((aIndex + 922U) & W_KEY1);
        const std::size_t aDestinationIndex = 1U * (S_HALF >> 1U) + 2U * W_KEY + aIndex;

        std::uint16_t aFoldValue = 0U;
        aFoldValue |= static_cast<std::uint16_t>(aSourceLaneD[aSourceIndexA]) << 0U;
        aFoldValue |= static_cast<std::uint16_t>(aSourceLaneB[aSourceIndexB]) << 8U;
        aFoldValue = TwistMix16::DiffuseA(aFoldValue);

        aStageOneLaneB[aDestinationIndex] = static_cast<std::uint8_t>(aFoldValue >> 0U);
    }

    // Destination B, block 3: source C half 0 block 6 + source D half 0 block 1
    for (std::size_t aIndex = 0U; aIndex < W_KEY; ++aIndex) {
        const std::size_t aSourceIndexA = 0U * S_HALF + 6U * W_KEY + ((aIndex + 877U) & W_KEY1);
        const std::size_t aSourceIndexB = 0U * S_HALF + 1U * W_KEY + ((aIndex + 832U) & W_KEY1);
        const std::size_t aDestinationIndex = 1U * (S_HALF >> 1U) + 3U * W_KEY + aIndex;

        std::uint16_t aFoldValue = 0U;
        aFoldValue |= static_cast<std::uint16_t>(aSourceLaneC[aSourceIndexA]) << 0U;
        aFoldValue |= static_cast<std::uint16_t>(aSourceLaneD[aSourceIndexB]) << 8U;
        aFoldValue = TwistMix16::DiffuseA(aFoldValue);

        aStageOneLaneB[aDestinationIndex] = static_cast<std::uint8_t>(aFoldValue >> 8U);
    }

    // Destination C, block 0: source B half 1 block 6 + source A half 1 block 3
    for (std::size_t aIndex = 0U; aIndex < W_KEY; ++aIndex) {
        const std::size_t aSourceIndexA = 1U * S_HALF + 6U * W_KEY + ((aIndex + 787U) & W_KEY1);
        const std::size_t aSourceIndexB = 1U * S_HALF + 3U * W_KEY + ((aIndex + 742U) & W_KEY1);
        const std::size_t aDestinationIndex = 1U * (S_HALF >> 1U) + 0U * W_KEY + aIndex;

        std::uint16_t aFoldValue = 0U;
        aFoldValue |= static_cast<std::uint16_t>(aSourceLaneB[aSourceIndexA]) << 8U;
        aFoldValue |= static_cast<std::uint16_t>(aSourceLaneA[aSourceIndexB]) << 0U;
        aFoldValue = TwistMix16::DiffuseA(aFoldValue);

        aStageOneLaneC[aDestinationIndex] = static_cast<std::uint8_t>(aFoldValue >> 0U);
    }

    // Destination C, block 1: source A half 1 block 6 + source C half 0 block 1
    for (std::size_t aIndex = 0U; aIndex < W_KEY; ++aIndex) {
        const std::size_t aSourceIndexA = 1U * S_HALF + 6U * W_KEY + ((aIndex + 697U) & W_KEY1);
        const std::size_t aSourceIndexB = 0U * S_HALF + 1U * W_KEY + ((aIndex + 652U) & W_KEY1);
        const std::size_t aDestinationIndex = 1U * (S_HALF >> 1U) + 1U * W_KEY + aIndex;

        std::uint16_t aFoldValue = 0U;
        aFoldValue |= static_cast<std::uint16_t>(aSourceLaneA[aSourceIndexA]) << 8U;
        aFoldValue |= static_cast<std::uint16_t>(aSourceLaneC[aSourceIndexB]) << 0U;
        aFoldValue = TwistMix16::DiffuseA(aFoldValue);

        aStageOneLaneC[aDestinationIndex] = static_cast<std::uint8_t>(aFoldValue >> 8U);
    }

    // Destination C, block 2: source C half 0 block 4 + source D half 0 block 4
    for (std::size_t aIndex = 0U; aIndex < W_KEY; ++aIndex) {
        const std::size_t aSourceIndexA = 0U * S_HALF + 4U * W_KEY + ((aIndex + 607U) & W_KEY1);
        const std::size_t aSourceIndexB = 0U * S_HALF + 4U * W_KEY + ((aIndex + 562U) & W_KEY1);
        const std::size_t aDestinationIndex = 1U * (S_HALF >> 1U) + 2U * W_KEY + aIndex;

        std::uint16_t aFoldValue = 0U;
        aFoldValue |= static_cast<std::uint16_t>(aSourceLaneC[aSourceIndexA]) << 8U;
        aFoldValue |= static_cast<std::uint16_t>(aSourceLaneD[aSourceIndexB]) << 0U;
        aFoldValue = TwistMix16::DiffuseA(aFoldValue);

        aStageOneLaneC[aDestinationIndex] = static_cast<std::uint8_t>(aFoldValue >> 8U);
    }

    // Destination C, block 3: source D half 0 block 7 + source B half 1 block 1
    for (std::size_t aIndex = 0U; aIndex < W_KEY; ++aIndex) {
        const std::size_t aSourceIndexA = 0U * S_HALF + 7U * W_KEY + ((aIndex + 517U) & W_KEY1);
        const std::size_t aSourceIndexB = 1U * S_HALF + 1U * W_KEY + ((aIndex + 472U) & W_KEY1);
        const std::size_t aDestinationIndex = 1U * (S_HALF >> 1U) + 3U * W_KEY + aIndex;

        std::uint16_t aFoldValue = 0U;
        aFoldValue |= static_cast<std::uint16_t>(aSourceLaneD[aSourceIndexA]) << 8U;
        aFoldValue |= static_cast<std::uint16_t>(aSourceLaneB[aSourceIndexB]) << 0U;
        aFoldValue = TwistMix16::DiffuseA(aFoldValue);

        aStageOneLaneC[aDestinationIndex] = static_cast<std::uint8_t>(aFoldValue >> 0U);
    }

    // Destination D, block 0: source B half 1 block 4 + source D half 0 block 2
    for (std::size_t aIndex = 0U; aIndex < W_KEY; ++aIndex) {
        const std::size_t aSourceIndexA = 1U * S_HALF + 4U * W_KEY + ((aIndex + 427U) & W_KEY1);
        const std::size_t aSourceIndexB = 0U * S_HALF + 2U * W_KEY + ((aIndex + 382U) & W_KEY1);
        const std::size_t aDestinationIndex = 1U * (S_HALF >> 1U) + 0U * W_KEY + aIndex;

        std::uint16_t aFoldValue = 0U;
        aFoldValue |= static_cast<std::uint16_t>(aSourceLaneB[aSourceIndexA]) << 0U;
        aFoldValue |= static_cast<std::uint16_t>(aSourceLaneD[aSourceIndexB]) << 8U;
        aFoldValue = TwistMix16::DiffuseA(aFoldValue);

        aStageOneLaneD[aDestinationIndex] = static_cast<std::uint8_t>(aFoldValue >> 8U);
    }

    // Destination D, block 1: source C half 0 block 7 + source B half 1 block 7
    for (std::size_t aIndex = 0U; aIndex < W_KEY; ++aIndex) {
        const std::size_t aSourceIndexA = 0U * S_HALF + 7U * W_KEY + ((aIndex + 337U) & W_KEY1);
        const std::size_t aSourceIndexB = 1U * S_HALF + 7U * W_KEY + ((aIndex + 292U) & W_KEY1);
        const std::size_t aDestinationIndex = 1U * (S_HALF >> 1U) + 1U * W_KEY + aIndex;

        std::uint16_t aFoldValue = 0U;
        aFoldValue |= static_cast<std::uint16_t>(aSourceLaneC[aSourceIndexA]) << 0U;
        aFoldValue |= static_cast<std::uint16_t>(aSourceLaneB[aSourceIndexB]) << 8U;
        aFoldValue = TwistMix16::DiffuseA(aFoldValue);

        aStageOneLaneD[aDestinationIndex] = static_cast<std::uint8_t>(aFoldValue >> 8U);
    }

    // Destination D, block 2: source A half 1 block 1 + source C half 0 block 2
    for (std::size_t aIndex = 0U; aIndex < W_KEY; ++aIndex) {
        const std::size_t aSourceIndexA = 1U * S_HALF + 1U * W_KEY + ((aIndex + 247U) & W_KEY1);
        const std::size_t aSourceIndexB = 0U * S_HALF + 2U * W_KEY + ((aIndex + 202U) & W_KEY1);
        const std::size_t aDestinationIndex = 1U * (S_HALF >> 1U) + 2U * W_KEY + aIndex;

        std::uint16_t aFoldValue = 0U;
        aFoldValue |= static_cast<std::uint16_t>(aSourceLaneA[aSourceIndexA]) << 0U;
        aFoldValue |= static_cast<std::uint16_t>(aSourceLaneC[aSourceIndexB]) << 8U;
        aFoldValue = TwistMix16::DiffuseA(aFoldValue);

        aStageOneLaneD[aDestinationIndex] = static_cast<std::uint8_t>(aFoldValue >> 0U);
    }

    // Destination D, block 3: source D half 0 block 5 + source A half 1 block 4
    for (std::size_t aIndex = 0U; aIndex < W_KEY; ++aIndex) {
        const std::size_t aSourceIndexA = 0U * S_HALF + 5U * W_KEY + ((aIndex + 157U) & W_KEY1);
        const std::size_t aSourceIndexB = 1U * S_HALF + 4U * W_KEY + ((aIndex + 112U) & W_KEY1);
        const std::size_t aDestinationIndex = 1U * (S_HALF >> 1U) + 3U * W_KEY + aIndex;

        std::uint16_t aFoldValue = 0U;
        aFoldValue |= static_cast<std::uint16_t>(aSourceLaneD[aSourceIndexA]) << 8U;
        aFoldValue |= static_cast<std::uint16_t>(aSourceLaneA[aSourceIndexB]) << 0U;
        aFoldValue = TwistMix16::DiffuseA(aFoldValue);

        aStageOneLaneD[aDestinationIndex] = static_cast<std::uint8_t>(aFoldValue >> 0U);
    }

    // Fold Stage II — 4 x 8,192 bytes into 4 x W_KEY bytes.

    // Key piece A
    for (std::size_t aIndex = 0U; aIndex < W_KEY; ++aIndex) {
        const std::size_t aSourceIndexA = 1U * (S_HALF >> 1U) + 2U * W_KEY + ((aIndex + 953U) & W_KEY1);
        const std::size_t aSourceIndexB = 1U * (S_HALF >> 1U) + 3U * W_KEY + ((aIndex + 908U) & W_KEY1);
        const std::size_t aSourceIndexC = 1U * (S_HALF >> 1U) + 3U * W_KEY + ((aIndex + 863U) & W_KEY1);
        const std::size_t aSourceIndexD = 1U * (S_HALF >> 1U) + 0U * W_KEY + ((aIndex + 818U) & W_KEY1);
        const std::size_t aDestinationIndex = 1U * W_KEY + aIndex;

        std::uint32_t aFoldValue = 0U;
        aFoldValue |= static_cast<std::uint32_t>(aStageOneLaneA[aSourceIndexA]) << 16U;
        aFoldValue |= static_cast<std::uint32_t>(aStageOneLaneB[aSourceIndexB]) << 24U;
        aFoldValue |= static_cast<std::uint32_t>(aStageOneLaneC[aSourceIndexC]) << 8U;
        aFoldValue |= static_cast<std::uint32_t>(aStageOneLaneD[aSourceIndexD]) << 0U;
        aFoldValue = TwistMix32::DiffuseA(aFoldValue);

        aStageTwoLaneA[aDestinationIndex] = static_cast<std::uint8_t>(aFoldValue >> 0U);
    }

    // Key piece B
    for (std::size_t aIndex = 0U; aIndex < W_KEY; ++aIndex) {
        const std::size_t aSourceIndexA = 1U * (S_HALF >> 1U) + 0U * W_KEY + ((aIndex + 773U) & W_KEY1);
        const std::size_t aSourceIndexB = 1U * (S_HALF >> 1U) + 0U * W_KEY + ((aIndex + 728U) & W_KEY1);
        const std::size_t aSourceIndexC = 1U * (S_HALF >> 1U) + 2U * W_KEY + ((aIndex + 683U) & W_KEY1);
        const std::size_t aSourceIndexD = 1U * (S_HALF >> 1U) + 3U * W_KEY + ((aIndex + 638U) & W_KEY1);
        const std::size_t aDestinationIndex = 1U * W_KEY + aIndex;

        std::uint32_t aFoldValue = 0U;
        aFoldValue |= static_cast<std::uint32_t>(aStageOneLaneA[aSourceIndexA]) << 0U;
        aFoldValue |= static_cast<std::uint32_t>(aStageOneLaneB[aSourceIndexB]) << 8U;
        aFoldValue |= static_cast<std::uint32_t>(aStageOneLaneC[aSourceIndexC]) << 16U;
        aFoldValue |= static_cast<std::uint32_t>(aStageOneLaneD[aSourceIndexD]) << 24U;
        aFoldValue = TwistMix32::DiffuseA(aFoldValue);

        aStageTwoLaneB[aDestinationIndex] = static_cast<std::uint8_t>(aFoldValue >> 24U);
    }

    // Key piece C
    for (std::size_t aIndex = 0U; aIndex < W_KEY; ++aIndex) {
        const std::size_t aSourceIndexA = 1U * (S_HALF >> 1U) + 3U * W_KEY + ((aIndex + 593U) & W_KEY1);
        const std::size_t aSourceIndexB = 1U * (S_HALF >> 1U) + 1U * W_KEY + ((aIndex + 548U) & W_KEY1);
        const std::size_t aSourceIndexC = 1U * (S_HALF >> 1U) + 1U * W_KEY + ((aIndex + 503U) & W_KEY1);
        const std::size_t aSourceIndexD = 1U * (S_HALF >> 1U) + 1U * W_KEY + ((aIndex + 458U) & W_KEY1);
        const std::size_t aDestinationIndex = 1U * W_KEY + aIndex;

        std::uint32_t aFoldValue = 0U;
        aFoldValue |= static_cast<std::uint32_t>(aStageOneLaneA[aSourceIndexA]) << 8U;
        aFoldValue |= static_cast<std::uint32_t>(aStageOneLaneB[aSourceIndexB]) << 0U;
        aFoldValue |= static_cast<std::uint32_t>(aStageOneLaneC[aSourceIndexC]) << 24U;
        aFoldValue |= static_cast<std::uint32_t>(aStageOneLaneD[aSourceIndexD]) << 16U;
        aFoldValue = TwistMix32::DiffuseA(aFoldValue);

        aStageTwoLaneC[aDestinationIndex] = static_cast<std::uint8_t>(aFoldValue >> 16U);
    }

    // Key piece D
    for (std::size_t aIndex = 0U; aIndex < W_KEY; ++aIndex) {
        const std::size_t aSourceIndexA = 1U * (S_HALF >> 1U) + 1U * W_KEY + ((aIndex + 413U) & W_KEY1);
        const std::size_t aSourceIndexB = 1U * (S_HALF >> 1U) + 2U * W_KEY + ((aIndex + 368U) & W_KEY1);
        const std::size_t aSourceIndexC = 1U * (S_HALF >> 1U) + 0U * W_KEY + ((aIndex + 323U) & W_KEY1);
        const std::size_t aSourceIndexD = 1U * (S_HALF >> 1U) + 2U * W_KEY + ((aIndex + 278U) & W_KEY1);
        const std::size_t aDestinationIndex = 1U * W_KEY + aIndex;

        std::uint32_t aFoldValue = 0U;
        aFoldValue |= static_cast<std::uint32_t>(aStageOneLaneA[aSourceIndexA]) << 16U;
        aFoldValue |= static_cast<std::uint32_t>(aStageOneLaneB[aSourceIndexB]) << 8U;
        aFoldValue |= static_cast<std::uint32_t>(aStageOneLaneC[aSourceIndexC]) << 0U;
        aFoldValue |= static_cast<std::uint32_t>(aStageOneLaneD[aSourceIndexD]) << 24U;
        aFoldValue = TwistMix32::DiffuseA(aFoldValue);

        aStageTwoLaneD[aDestinationIndex] = static_cast<std::uint8_t>(aFoldValue >> 8U);
    }
}

